design\activity\card__eb3a4820-0edb-4161-8fe5-926a981d2c8f.json:157:          "content": "import type { ActionFile } from './action_types'\r\nimport type { ActionSchedule } from './action_schedule_types'\r\nimport { DEFAULT_COLOR_SCHEME } from '../theme/theme_config'\r\nimport type { ProjectBackgroundShade } from '../theme/project_background_shade'\r\nimport { DEFAULT_CARD_SEPARATOR, type CardSeparator } from './card_identifiers'\r\n\r\nexport const DEFAULT_WORKING_FOLDER = 'active'\r\nexport const DEFAULT_ACTIONS_FOLDER = 'actions'\r\nexport const DEFAULT_ARCHIVED_FOLDER = 'archived'\r\nexport const DEFAULT_PROJECT_FOLDER = 'design'\r\nexport const DEFAULT_RELEASES_FOLDER = 'history'\r\nexport const DEFAULT_DIFF_COMMAND = 'git show {{commit}}'\r\nexport const AUTO_COMMIT_DELAY_MS = 30000\r\n\r\n/** Card type id; projects can configure custom types beyond the default feature/job/bug. */\r\nexport type CardType = string\r\nexport type PushMode = 'auto' | 'manual'\r\n\r\nexport interface CardTypeConfig {\r\n    color: string\r\n    idPrefix: string\r\n    label: string\r\n    type: CardType\r\n}\r\n\r\nexport interface StateConfig {\r\n    alwaysVisible: boolean\r\n    color?: string\r\n    state: string\r\n}\r\n\r\nexport interface ProjectConfig {\r\n    actionsFolder: string\r\n    archivedFolder: string\r\n    backgroundShade: ProjectBackgroundShade\r\n    cardBodyTemplate: string\r\n    cardSeparator: CardSeparator\r\n    cardTypes: CardTypeConfig[]\r\n    diffCommand: string\r\n    projectFolder: string\r\n    pushMode: PushMode\r\n    releasesFolder: string\r\n    states: StateConfig[]\r\n    workingFolder: string\r\n}\r\n\r\n/** How a file's `content` is encoded for the storage write path. Binary assets use base64. */\r\nexport type FileEncoding = 'utf-8' | 'base64'\r\n\r\nexport interface MarkdownFile {\r\n    content: string\r\n    encoding?: FileEncoding\r\n    path: string\r\n    sha?: string\r\n}\r\n\r\nexport interface ProjectAsset {\r\n    content: string\r\n    contentType: string\r\n    encoding: 'base64'\r\n    path: string\r\n}\r\n\r\nexport interface CardHeader {\r\n    affects: string[]\r\n    after: string | null\r\n    /** Terminal conversation references inside activity files; the name mirrors the persisted `agents` field. */\r\n    agentLogReferences: string[]\r\n    author: string | null\r\n    id: string\r\n    internalId: string | null\r\n    owner: string | null\r\n    policy: Record<string, boolean>\r\n    status: string | null\r\n    title: string\r\n    worktree?: number | null\r\n    worktreeError?: string | null\r\n    worktreeValue?: string | null\r\n}\r\n\r\nexport interface ProjectCard {\r\n    agentConversationErrors: AgentConversationError[]\r\n    agentConversations: AgentConversation[]\r\n    content: string\r\n    header: CardHeader\r\n    /** Raw frontmatter fields as written in the file, including unknown keys. */\r\n    headerFields: Record<string, string | string[] | Record<string, string>>\r\n    isActive: boolean\r\n    path: string\r\n    sha?: string\r\n}\r\n\r\nexport interface ProjectSnapshot {\r\n    activeCards: ProjectCard[]\r\n    backgroundCards: ProjectCard[]\r\n    repositoryFiles: string[]\r\n    workingFolder: string\r\n}\r\n\r\nexport interface CardDraft {\r\n    body: string\r\n    bodyIncludesTemplate?: boolean\r\n    title: string\r\n    type: CardType\r\n}\r\n\r\nexport interface ProjectReference {\r\n    branch: string\r\n    id: string\r\n    owner?: string\r\n    repository?: string\r\n    rootPath?: string\r\n}\r\n\r\nexport interface WorktreeRecord {\r\n    branch: string | null\r\n    error: string | null\r\n    parkingBranch: string\r\n    path: string\r\n    status: WorktreeStatus\r\nimport { createCardFile } from '../../data/card_naming'\nimport { computeMove, type CardMoveUpdate } from '../../data/card_ordering'\nimport type { CardDraft, MarkdownFile } from '../../data/data_types'\nimport type { OpenDocumentSaveReference } from '../open_files_service'\nimport { telemetryService } from '../telemetry/telemetry_service'\nimport { CardArchiveOperations } from './card_archive_operations'\nimport { CardInternalIdOperations } from './card_internal_id_operations'\nimport {\n    attachSaveReference,\n    CardOperationContext,\n    type CardOperationsDeps,\n    type CommitRequest,\n} from './card_operation_context'\nimport { CardRenameOperations } from './card_rename_operations'\nimport { markdownParsingService } from './markdown_parsing_service'\nimport { ProjectFileOperations } from './project_file_operations'\n\nexport type { CardOperationsDeps }\n\n/** The card-facing surface of the data service, delegating to focused operation modules. */\nexport class CardOperations {\n    private readonly context: CardOperationContext\n    private readonly archives: CardArchiveOperations\n    private readonly internalIds: CardInternalIdOperations\n    private readonly projectFiles: ProjectFileOperations\n    private readonly renames: CardRenameOperations\n    private readonly triggerStateActions: (cardPath: string, state: string) => void\n\n    constructor(\n        dependencies: CardOperationsDeps,\n        triggerStateActions: (cardPath: string, state: string) => void,\n    ) {\n        this.context = new CardOperationContext(dependencies)\n        this.triggerStateActions = triggerStateActions\n        this.archives = new CardArchiveOperations(this.context, triggerStateActions)\n        this.renames = new CardRenameOperations(this.context)\n        this.internalIds = new CardInternalIdOperations(this.context, () => this.renames.reset())\n        this.projectFiles = new ProjectFileOperations(this.context)\n    }\n\n    async createCard(draft: CardDraft) {\n        const { config, project } = this.context.requireProject('create a card')\n        const { dependencies } = this.context\n\n        const file = createCardFile(\n            dependencies.files(),\n            config.workingFolder,\n            config.cardSeparator,\n            config.cardTypes,\n            config.cardBodyTemplate,\n            config.states[0].state,\n            draft,\n        )\n        dependencies.replaceFiles([...dependencies.files(), file], config.workingFolder)\n        await this.context.commitAndMergeFiles({\n            branch: project.branch,\n            files: [file],\n            message: `Create ${file.path}`,\n        }, [file])\n        await this.context.pushCreatedItem('Card')\n\n        dependencies.refreshSnapshot(config.workingFolder)\n        telemetryService.trackEvent('create_card')\n\n        return file\n    }\n\n    createFolder(parentDirectory: string, name: string) {\n        return this.projectFiles.createFolder(parentDirectory, name)\n    }\n\n    createMarkdownFile(parentDirectory: string, name: string) {\n        return this.projectFiles.createMarkdownFile(parentDirectory, name)\n    }\n\n    updateCardBody(path: string, body: string, saveReference?: OpenDocumentSaveReference) {\n        const existingFile = this.context.dependencies.requireFile(path)\n\n        return this.saveFile(\n            { content: markdownParsingService.replaceBody(existingFile.content, body), path, sha: existingFile.sha },\n            saveReference,\n        )\n    }\n\n    updateCardAffects(path: string, affects: string[]) {\n        return this.context.saveCardContentChange(path, (content) => markdownParsingService.setAffects(content, affects))\n    }\n\n    updateCardHeaderFields(path: string, updates: Record<string, string>, saveReference?: OpenDocumentSaveReference) {\n        return this.context.saveCardContentChange(\n            path,\n            (content) => markdownParsingService.rewriteHeader(content, updates),\n            saveReference,\n        )\n    }\n\n    updateCardWorktree(path: string, worktree: number | null) {\n        return this.context.saveCardContentChange(path, (content) => markdownParsingService.setWorktree(content, worktree))\n    }\n\n    toggleCardPolicy(path: string, policyKey: string, saveReference?: OpenDocumentSaveReference) {\n        const { config } = this.context.dependencies.requireDependencies()\n        const existingFile = this.context.dependencies.requireFile(path)\n        const card = markdownParsingService.parseCard(existingFile, config.workingFolder)\n        const enabled = card.header.policy[policyKey] ?? false\n\n        return this.context.saveCardContentChange(\n            path,\n            (content) => markdownParsingService.setPolicyFlag(content, policyKey, !enabled),\n            saveReference,\n        )\n    }\n\n    ensureCardInternalIds() {\n        return this.internalIds.ensureCardInternalIds()\n    }\n\n    updateCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {\n        return this.renames.updateCardTitle(path, title, saveReference)\n    }\n\n    async moveCard(cardPath: string, targetStatus: string, targetIndex: number) {\n        if (targetStatus === 'archived') return this.archives.archiveCard(cardPath, targetIndex)\n\n        const activeCards = this.context.dependencies.snapshot()?.activeCards ?? []\n        const movedCard = activeCards.find((card) => card.path === cardPath)\n        const previousStatus = movedCard?.header.status ?? null\n        const updates = computeMove(activeCards, cardPath, targetStatus, targetIndex)\n\n        this.saveCardMoveUpdates(cardPath, updates)\n\n        if (movedCard && previousStatus !== targetStatus) this.triggerStateActions(movedCard.path, targetStatus)\n\n        return updates\n    }\n\n    /** Applies every ordering link from one move to local state and one persistence batch. */\n    private saveCardMoveUpdates(cardPath: string, updates: CardMoveUpdate[]) {\n        if (updates.length === 0) return\n\n        const { commitBatcher, project } = this.context.requireProject('move a card')\n        const openDocumentsByPath = new Map(updates.map(({ path }) => [path, this.context.findOpenCardDocument(path)]))\n        const updatedFiles = this.context.applyOrderingUpdates(updates)\n        this.context.replaceUpdatedFiles(updatedFiles)\n\n        const changes = updatedFiles.map((file) => attachSaveReference(\n            file,\n            this.context.resyncOpenCardDocument(openDocumentsByPath.get(file.path) ?? null, file.path, undefined, 'Moved'),\n        ))\n        commitBatcher.schedule(project.branch, changes, `Move ${cardPath}`)\n        this.context.dependencies.dispatchChanged()\n    }\n\n    async deleteCard(path: string) {\n        const card = this.context.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === path)\n        if (!card) throw new Error(`Cannot delete an active card that is not loaded: ${path}`)\n\n        return this.projectFiles.deleteProjectFile(path, true)\n    }\n\n    async deleteFile(path: string) {\n        const { dependencies } = this.context\n        const loadedFile = dependencies.files().some((file) => file.path === path)\n        const repositoryFile = dependencies.snapshot()?.repositoryFiles.includes(path) ?? false\n        if (!loadedFile && !repositoryFile) throw new Error(`Cannot delete a file that is not loaded: ${path}`)\n\n        const activeCard = dependencies.snapshot()?.activeCards.some((card) => card.path === path) ?? false\n\n        return this.projectFiles.deleteProjectFile(path, activeCard)\n    }\n\n    deleteFolder(path: string) {\n        return this.projectFiles.deleteFolder(path)\n    }\n\n    saveFile(file: MarkdownFile, saveReference?: OpenDocumentSaveReference) {\n        return this.context.saveFile(file, saveReference)\n    }\n\n    saveProjectFile(file: MarkdownFile, message: string) {\n        return this.projectFiles.saveProjectFile(file, message)\n    }\n\n    flushPendingCommits() {\n        return this.context.flushPendingCommits()\n    }\n\n    commitFiles(request: CommitRequest) {\n        return this.context.commitFiles(request)\n    }\n\n    commitAndMergeFiles(request: CommitRequest, fallbackFiles: MarkdownFile[] = []) {\n        return this.context.commitAndMergeFiles(request, fallbackFiles)\n    }\n}\n\r\n}\r\n\r\n/** Owns project menu service calls and non-dialog session state. */\r\nexport function useProjectToolbarMenuActions(args: UseProjectToolbarMenuActionsArgs) {\r\n    const { accessToken, isGithubAuthenticated, onCloseDialog, onOpenDialog } = args\r\n    const { project, snapshot } = useProjectState()\r\n    const projectSession = useProjectSession()\r\n    const projectConfig = useProjectConfig()\r\n    const electronBridge = useMemo(() => getElectronDataBridge(), [])\r\n    const [branches, setBranches] = useState<BranchReference[]>(EMPTY_BRANCHES)\r\n    const [isReleaseCompleting, setIsReleaseCompleting] = useState(false)\r\n    const [projectOpenResolution, setProjectOpenResolution] = useState<ProjectOpenResolution | null>(null)\r\n    const [initialProjectSource, setInitialProjectSource] = useState<ProjectDialogSource | null>(null)\r\n    const [initialRemoteProject, setInitialRemoteProject] = useState<ProjectReference | null>(null)\r\n    const [repositories, setRepositories] = useState<RepositoryReference[]>(EMPTY_REPOSITORIES)\r\n    const [switchBranch, setSwitchBranch] = useState(project?.branch ?? '')\r\n    const activeCards = snapshot?.activeCards ?? []\r\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\r\n    const cardBodyTemplate = projectConfig?.cardBodyTemplate ?? DEFAULT_CARD_BODY_TEMPLATE\r\n    const pushMode = (projectConfig?.pushMode ?? 'auto') as PushMode\r\n\r\n    const closeDialog = useCallback(() => {\r\n        onCloseDialog()\r\n        setProjectOpenResolution(null)\r\n        projectSessionService.setError(null)\r\n    }, [onCloseDialog])\r\n\r\n    const openProject = useCallback(async (storageType: StorageType, nextProject: ProjectReference) => {\r\n        setProjectOpenResolution(null)\r\n\r\n        try {\r\n            const resolution = await projectSessionService.openProject(storageType, nextProject, accessToken)\r\n            if (resolution) {\r\n                setProjectOpenResolution(resolution)\r\n                onOpenDialog('open')\r\n\r\n                return\r\n            }\r\n\r\n            closeDialog()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }, [accessToken, closeDialog, onOpenDialog])\r\n\r\n    const openElectronProject = useCallback(async () => {\r\n        if (!electronBridge) return\r\n\r\n        let nextProject: ProjectReference | null\r\n        try {\r\n            nextProject = await electronBridge.openProjectFolder()\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: 'Local project selection failed' })\r\n\r\n            return\r\n        }\r\n\r\n        if (nextProject) await openProject('local', nextProject)\r\n    }, [electronBridge, openProject])\r\n\r\n    const loadRepositories = useCallback(async () => {\r\n        try {\r\n            setRepositories(await projectSessionService.listRepositories(accessToken))\r\n        } catch {\r\n            setRepositories(EMPTY_REPOSITORIES)\r\n        }\r\n    }, [accessToken])\r\n\r\n    const loadSwitchBranches = useCallback(async () => {\r\n        if (!project) return\r\n\r\n        try {\r\n            const storageType = project.rootPath ? 'local' : 'github'\r\n            const nextBranches = await projectSessionService.listBranches(storageType, project, accessToken)\r\n            setBranches(nextBranches)\r\n            setSwitchBranch(branchValue(nextBranches, project.branch))\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }, [accessToken, project])\r\n\r\n    useEffect(() => {\r\n        const handleOpenProjectDialog = (event: Event) => {\r\n            if (electronBridge) {\r\n                void openElectronProject()\r\n                return\r\n            }\r\n\r\n            const detail = (event as CustomEvent<OpenProjectDialogDetail>).detail\r\n            setInitialProjectSource(detail?.source ?? null)\r\n            setInitialRemoteProject(detail?.project ?? null)\r\n            setProjectOpenResolution(detail?.resolution ?? null)\r\n            onOpenDialog('open')\r\n            if (isGithubAuthenticated) void loadRepositories()\r\n        }\r\n\r\n        window.addEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)\r\n\r\n        return () => window.removeEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)\r\n    }, [electronBridge, isGithubAuthenticated, loadRepositories, onOpenDialog, openElectronProject])\r\n\r\n    useEffect(() => {\r\n        const handleOpenNewCardDialog = () => {\r\n            if (project) onOpenDialog('card')\r\n        }\r\n\r\n        window.addEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)\r\n\r\n        return () => window.removeEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)\r\n    }, [onOpenDialog, project])\r\n\r\n    const openProjectDialog = () => {\r\n        if (electronBridge) {\r\n            void openElectronProject()\r\n            return\r\n        }\r\n\r\n        setInitialProjectSource(null)\r\n        setInitialRemoteProject(null)\r\n        onOpenDialog('open')\r\n        if (isGithubAuthenticated) void loadRepositories()\r\n    }\r\n\r\n    const openBranchDialog = () => {\r\n        onOpenDialog('branch')\r\n        void loadSwitchBranches()\r\n    }\r\n\r\n    const clearOpenDialogState = () => {\r\n        setBranches(EMPTY_BRANCHES)\r\n        setProjectOpenResolution(null)\r\n    }\r\n\r\n    const loadRepositoryBranches = async (repository: RepositoryReference) => {\r\n        try {\r\n            const nextBranches = await projectSessionService.listBranches('github', repository, accessToken)\r\n            setBranches(nextBranches)\r\n\r\n            return nextBranches\r\n        } catch {\r\n            setBranches(EMPTY_BRANCHES)\r\n\r\n            return EMPTY_BRANCHES\r\n        }\r\n    }\r\n\r\n    const loadManualBranches = async (owner: string, repositoryName: string) => {\r\n        try {\r\n            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken)\r\n            setBranches(result.branches)\r\n\r\n            return result\r\n        } catch {\r\n            return null\r\n        }\r\n    }\r\n\r\n    const createRemoteProject = (rootPath: string, branch: string): ProjectReference | null => {\r\n        try {\r\n            if (rootPath.length === 0) throw new Error('Missing remote project root path')\r\n\r\n            return { branch: branch || 'main', id: rootPath, rootPath }\r\n        } catch (error) {\r\n            dialogService.error(error, { fallbackMessage: 'Remote project could not be created' })\r\n\r\n            return null\r\n        }\r\n    }\r\n\r\n    const loadRemoteBranches = async (endpoint: string, token: string, rootPath: string, branch: string) => {\r\n        const remoteProject = createRemoteProject(rootPath, branch)\r\n        if (!remoteProject) {\r\n            setBranches(EMPTY_BRANCHES)\r\n\r\n            return EMPTY_BRANCHES\r\n        }\r\n\r\n        projectSessionService.configureRemote(endpoint, token)\r\n\r\n        try {\r\n            const nextBranches = await projectSessionService.listBranches('remote', remoteProject, accessToken)\r\n            setBranches(nextBranches)\r\n\r\n            return nextBranches\r\n        } catch {\r\n            setBranches(EMPTY_BRANCHES)\r\n\r\n            return EMPTY_BRANCHES\r\n        }\r\n    }\r\n\r\n    const openGithubProject = async (owner: string, repositoryName: string, branch: string) => {\r\n        try {\r\n            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken)\r\n            const fallbackBranches = branches.length > 0 ? branches : result.branches\r\n            const selectedBranch = branch || branchValue(fallbackBranches, result.repository.branch)\r\n            setBranches(fallbackBranches)\r\n            await openProject('github', { ...result.repository, branch: selectedBranch })\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const openRemoteProject = async (endpoint: string, token: string, nextProject: ProjectReference) => {\r\n        projectSessionService.configureRemote(endpoint, token)\r\n        await openProject('remote', nextProject)\r\n    }\r\n\r\n    const openWorkingFolder = async (folder: TopLevelFolderReference) => {\r\n        if (projectOpenResolution?.kind !== 'missing-working-folder') return\r\n\r\n        try {\r\n            await projectSessionService.openWorkingFolder(projectOpenResolution, folder, accessToken)\r\n            closeDialog()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const createWorkingFolder = async () => {\r\n        if (projectOpenResolution?.kind !== 'missing-working-folder') return\r\n\r\n        try {\r\n            await projectSessionService.createWorkingFolder(projectOpenResolution, accessToken)\r\n            closeDialog()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const createProjectFolders = async (projectFolder: string) => {\r\n        if (projectOpenResolution?.kind !== 'project-folder-setup') return\r\n\r\n        try {\r\n            await projectSessionService.createProjectFolders(projectOpenResolution, projectFolder, accessToken)\r\n            closeDialog()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const switchProjectBranch = async (branch: string) => {\r\n        try {\r\n            await projectSessionService.switchBranch(branch)\r\n            closeDialog()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        }\r\n    }\r\n\r\n    const completeRelease = async (releaseName: string) => {\r\n        setIsReleaseCompleting(true)\r\n        try {\r\n            await projectSessionService.completeRelease(releaseName)\r\n            closeDialog()\r\n        } catch {\r\n            // ProjectSessionService emits the user-visible error.\r\n        } finally {\r\n            setIsReleaseCompleting(false)\r\n        }\r\n    }\r\n\r\n    const createCard = async (draft: CardDraft) => {\r\n        await projectSessionService.createCard(draft)\r\n        closeDialog()\r\n    }\r\n\r\n    return {\r\n        activeCards,\r\n        branches,\r\n        cardBodyTemplate,\r\n        cardTypes,\r\n        clearOpenDialogState,\r\n        closeDialog,\r\n        commit: () => projectSessionService.commit(),\r\n        completeRelease,\r\n        initialProjectSource,\r\n        initialRemoteProject,\r\n        createCard,\r\n        createProjectFolders,\r\n        createRemoteProject,\r\n        createWorkingFolder,\r\n        isLoading: projectSession.isLoading,\r\n        isDesktopMode: !!electronBridge,\r\n        isProjectOpen: !!project,\r\n        isReleaseCompleting,\r\n        loadSwitchBranches,\r\n        loadManualBranches,\r\n        loadRemoteBranches,\r\n        loadRepositoryBranches,\r\nimport { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { DEFAULT_CARD_TYPES, type BranchReference, type ProjectReference, type RepositoryReference } from '../../../data/data_types'\nimport {\n    configureRemoteControlConnection,\n    REMOTE_CONTROL_ENDPOINT_KEY,\n    REMOTE_CONTROL_TOKEN_KEY,\n} from '../../../data/remote_control_connection'\nimport { AppThemeProvider } from '../../../theme/theme_provider'\nimport { BranchSwitchDialog } from './branch_switch_dialog'\nimport { CompleteReleaseDialog } from './complete_release_dialog'\nimport { NewCardDialog } from './new_card_dialog'\nimport { ProjectOpenDialog } from './project_open_dialog'\nimport { WorkingFolderChooserDialog } from './working_folder_chooser_dialog'\n\nconst BRANCHES: BranchReference[] = [{ name: 'main' }]\nconst PROJECT: ProjectReference = { branch: 'main', id: 'local', rootPath: 'C:/repo' }\nconst REPOSITORIES: RepositoryReference[] = [{ branch: 'main', id: 'octo/demo', owner: 'octo', repository: 'demo' }]\n\nfunction mockMatchMedia(matches: boolean) {\n    window.matchMedia = ((query: string) => ({\n        addEventListener: () => {},\n        addListener: () => {},\n        dispatchEvent: () => false,\n        matches,\n        media: query,\n        onchange: null,\n        removeEventListener: () => {},\n        removeListener: () => {},\n    })) as unknown as typeof window.matchMedia\n}\n\ndescribe('project dialog components', () => {\n    beforeEach(() => {\n        mockMatchMedia(false)\n    })\n\n    afterEach(() => {\n        cleanup()\n        vi.restoreAllMocks()\n        window.localStorage.removeItem(REMOTE_CONTROL_ENDPOINT_KEY)\n        window.localStorage.removeItem(REMOTE_CONTROL_TOKEN_KEY)\n    })\n\n    it('renders the open project dialog without mounting the menu', () => {\n        render(\n            <ProjectOpenDialog\n                branches={BRANCHES}\n                isDesktopMode={false}\n                isGithubAuthenticated\n                isLoading={false}\n                projectOpenResolution={null}\n                onBranchChange={vi.fn()}\n                onClose={vi.fn()}\n                onCreateProjectFolders={vi.fn()}\n                onCreateRemoteProject={vi.fn((rootPath, branch) => ({ branch, id: rootPath, rootPath }))}\n                onCreateWorkingFolder={vi.fn()}\n                onDiscardGithubPendingCommits={vi.fn()}\n                onLoadManualBranches={vi.fn(async () => ({ branches: BRANCHES, repository: REPOSITORIES[0] }))}\n                onLoadRemoteBranches={vi.fn(async () => BRANCHES)}\n                onOpenGithub={vi.fn()}\n                onOpenRemote={vi.fn()}\n                onRepositoryChange={vi.fn(async () => BRANCHES)}\n                onSourceChange={vi.fn()}\n                onUseWorkingFolder={vi.fn()}\n                open\n                pendingGithubConflictProject={null}\n                repositories={REPOSITORIES}\n            />,\n        )\n\n        expect(screen.getByRole('dialog', { name: 'Open project' })).toBeInTheDocument()\n        expect(screen.getByLabelText('Filter repositories')).toBeInTheDocument()\n    })\n\n    it('keeps branch entry editable when no branch options exist', () => {\n        const openGithub = vi.fn()\n\n        render(\n            <ProjectOpenDialog\n                branches={[]}\n                isDesktopMode={false}\n                isGithubAuthenticated\n                isLoading={false}\n                projectOpenResolution={null}\n                onBranchChange={vi.fn()}\n                onClose={vi.fn()}\n                onCreateProjectFolders={vi.fn()}\n                onCreateRemoteProject={vi.fn((rootPath, branch) => ({ branch, id: rootPath, rootPath }))}\n                onCreateWorkingFolder={vi.fn()}\n                onDiscardGithubPendingCommits={vi.fn()}\n                onLoadManualBranches={vi.fn(async () => ({ branches: BRANCHES, repository: REPOSITORIES[0] }))}\n                onLoadRemoteBranches={vi.fn(async () => BRANCHES)}\n                onOpenGithub={openGithub}\n                onOpenRemote={vi.fn()}\n                onRepositoryChange={vi.fn(async () => BRANCHES)}\n                onSourceChange={vi.fn()}\n                onUseWorkingFolder={vi.fn()}\n                open\n                pendingGithubConflictProject={null}\n                repositories={[]}\n            />,\n        )\n\n        fireEvent.change(screen.getByLabelText('Owner'), 