design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:94:          "content": "import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'\r\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\r\nimport { within } from '@testing-library/react'\r\nimport type { UseGithubAuthResult } from '../../auth/use_github_auth'\r\nimport type { ElectronActionBridge } from '../../data/electron_action_bridge'\r\nimport type { MarkdownFile, StorageService } from '../../data/data_types'\r\nimport { configService } from '../../services/config/config_service'\r\nimport { actionService } from '../../services/actions/action_service'\r\nimport { dataService } from '../../services/data/data_service'\r\nimport { projectPersistenceService } from '../../services/project/project_persistence_service'\r\nimport { openFilesService } from '../../services/open_files_service'\r\nimport * as searchRegexpAgent from '../../services/search/search_regexp_agent'\r\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\r\nimport { AppThemeProvider } from '../../theme/theme_provider'\r\nimport { DialogDisplay } from '../dialog_display'\r\nimport { MainWindow } from './main_window'\r\n\r\nconst auth: UseGithubAuthResult = {\r\n    accessToken: null,\r\n    errorMessage: null,\r\n    isAuthenticated: false,\r\n    isLoadingUser: false,\r\n    logout: vi.fn(),\r\n    savePersonalAccessToken: vi.fn(),\r\n    status: 'idle',\r\n    user: null,\r\n}\r\n\r\nfunction mainWindowElement(overrides?: Partial<Parameters<typeof MainWindow>[0]>) {\r\n    return (\r\n        <AppThemeProvider>\r\n            <DialogDisplay />\r\n            <MainWindow\r\n                auth={auth}\r\n                toolbarAction={<button type=\"button\">Action</button>}\r\n                {...overrides}\r\n            />\r\n        </AppThemeProvider>\r\n    )\r\n}\r\n\r\nfunction renderWindow(overrides?: Partial<Parameters<typeof MainWindow>[0]>) {\r\n    return render(mainWindowElement(overrides))\r\n}\r\n\r\nfunction installAgentBridge(stdout: string) {\r\n    const bridge: ElectronActionBridge = {\r\n        cancelActionExecution: vi.fn(async () => {}),\r\n        generateDiff: vi.fn(async () => ({ commit: '', files: [] })),\r\n        loadActionRunHistory: vi.fn(async () => []),\r\n        onActionExecution: vi.fn(() => () => {}),\r\n        openInEditor: vi.fn(async () => {}),\r\n        prepareActionPrompt: vi.fn(async () => ({ prompt: '' })),\r\n        runSearchRegexpAgent: vi.fn(async () => stdout),\r\n        startAction: vi.fn(async () => 'action-1'),\r\n    }\r\n    window.md2Actions = bridge\r\n\r\n    return bridge\r\n}\r\n\r\nfunction createStorage(files: MarkdownFile[] = []): StorageService {\r\n    return {\r\n        checkoutBranch: vi.fn(async (project, branch) => ({ ...project, branch })),\r\n        commit: vi.fn(async () => []),\r\n        createProject: vi.fn(async (project) => project),\r\n        deleteFile: vi.fn(),\r\n        deleteFolder: vi.fn(),\r\n        listBranches: vi.fn(async () => []),\r\n        listRepositories: vi.fn(async () => []),\r\n        listRepositoryFiles: vi.fn(async () => []),\r\n        listTopLevelFolders: vi.fn(async () => []),\r\n        loadActionFiles: vi.fn(async () => []),\r\n        loadProject: vi.fn(async () => ({ files, workingFolder: 'design' })),\r\n        loadProjectRoot: vi.fn(async () => ({ files, workingFolder: 'design' })),\r\n        loadProjectConfig: vi.fn(async () => ({ backgroundShade: 'blue' as const, projectFolder: '', workingFolder: 'design' })),\r\n        moveFiles: vi.fn(),\r\n        push: vi.fn(),\r\n        saveProjectConfig: vi.fn(),\r\n    }\r\n}\r\n\r\nasync function openProjectWithCards() {\r\n    const files = [\r\n        { content: '---\\nid: F-1\\ntitle: Root\\nstatus: active\\naffects:\\n---\\n\\n# Root', path: 'design/F-1-root.md' },\r\n        { content: '# Old', path: 'design/history/F-2-old.md' },\r\n    ]\r\n    openFilesService.init({ actionService, dataService })\r\n    projectPersistenceService.init({ actionService, dataService, openFilesService })\r\n    dataService.init({ storage: createStorage(files) })\r\n    const project = { branch: 'main', id: 'project', rootPath: 'C:/project' }\r\n    const snapshot = await dataService.projectLoading.openProject(project)\r\n\r\n    return { project, snapshot, storageType: 'local' as const }\r\n}\r\n\r\nfunction typeQuery(value: string) {\r\n    fireEvent.focus(screen.getByRole('textbox', { name: 'Search project' }))\r\n    fireEvent.change(screen.getByRole('textbox', { name: 'Search project' }), { target: { value } })\r\n}\r\n\r\nfunction mockMatchMedia(matches: boolean) {\r\n    window.matchMedia = ((query: string) => ({\r\n        addEventListener: () => {},\r\n        addListener: () => {},\r\n        dispatchEvent: () => false,\r\n        matches,\r\n        media: query,\r\n        onchange: null,\r\n        removeEventListener: () => {},\r\n        removeListener: () => {},\r\n    })) as unknown as typeof window.matchMedia\r\n}\r\n\r\ndescribe('MainWindow', () => {\r\n    beforeEach(() => {\r\n        configService.init({ desktopConfig: null })\r\n        openFilesService.init({ actionService, dataService })\r\n        projectPersistenceService.init({ actionService, dataService, openFilesService })\r\n        dataService.init({ storage: createStorage() })\r\n    })\r\n\r\n    afterEach(() => {\r\n        cleanup()\r\n        dataService.init({ storage: createStorage() })\r\n        configService.clear()\r\n        delete window.md2Actions\r\n        window.location.hash = ''\r\n        workspaceViewService.setViewMode('cards')\r\n        mockMatchMedia(false)\r\n    })\r\n\r\n    it('shows the workspace and status bar on desktop', () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()\r\n        expect(screen.getByRole('button', { name: 'Open project' })).toBeInTheDocument()\r\n        expect(screen.getByRole('heading', { name: 'No project open' })).toBeInTheDocument()\r\n        expect(screen.getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()\r\n        expect(screen.queryByRole('button', { name: 'Open menu' })).toBeNull()\r\n    })\r\n\r\n    it('shows card columns without a left navigation panel in card view', async () => {\r\n        mockMatchMedia(false)\r\n        await openProjectWithCards()\r\n        renderWindow()\r\n\r\n        expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\r\n        expect(within(screen.getByLabelText('Card columns')).getByText('Root')).toBeInTheDocument()\r\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('2cards')\r\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('1active')\r\n        expect(screen.queryByText('No project navigation available.')).toBeNull()\r\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\r\n        expect(screen.getByLabelText('File tree')).not.toBeVisible()\r\n    })\r\n\r\n    it('keeps text navigation hidden when the first project opens in card view', async () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\r\n\r\n        await openProjectWithCards()\r\n\r\n        await waitFor(() => {\r\n            expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\r\n            expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\r\n            expect(screen.getByLabelText('File tree')).not.toBeVisible()\r\n        })\r\n    })\r\n\r\n    it('switches from card view to text view on desktop without resetting back to cards', async () => {\r\n        mockMatchMedia(false)\r\n        await openProjectWithCards()\r\n        renderWindow()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\r\n\r\n        expect(await screen.findByLabelText('File tree')).toBeInTheDocument()\r\n        expect(screen.queryByRole('heading', { name: 'Files' })).toBeNull()\r\n        expect(screen.getByRole('separator', { name: 'Resize panels' })).toBeInTheDocument()\r\n    })\r\n\r\n    it('keeps the project workspace mounted while switching desktop views', async () => {\r\n        mockMatchMedia(false)\r\n        await openProjectWithCards()\r\n        renderWindow()\r\n        const workspace = screen.getByLabelText('Project workspace')\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\r\n        await screen.findByLabelText('File tree')\r\n\r\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Cards view' }))\r\n\r\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\r\n    })\r\n\r\n    it('moves the left panel content into a hamburger drawer on mobile', () => {\r\n        mockMatchMedia(true)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\r\n        expect(screen.queryByRole('button', { name: /Switch to (dark|light) theme/ })).toBeNull()\r\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\r\n        expect(screen.getByText('No project navigation available.')).toBeInTheDocument()\r\n        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()\r\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\r\n    })\r\n\r\n    it('opens mobile search from a toolbar icon', () => {\r\n        mockMatchMedia(true)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByRole('textbox', { name: 'Search project' })).toBeNull()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Search' }))\r\n\r\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveFocus()\r\n    })\r\n\r\n    it('keeps GitHub authentication in the mobile drawer footer', () => {\r\n        mockMatchMedia(true)\r\n        renderWindow()\r\n\r\n        expect(screen.queryByRole('button', { name: 'GitHub account' })).toBeNull()\r\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\r\n        const drawerFooter = screen.getByRole('contentinfo')\r\n        fireEvent.click(within(drawerFooter).getByRole('button', { name: 'GitHub account' }))\r\n\r\n        expect(screen.getByLabelText('Personal access token')).toBeInTheDocument()\r\n    })\r\n\r\n    it('opens the config page from the toolbar', () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\r\n\r\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\r\n        expect(window.location.hash).toBe('#/config')\r\n    })\r\n\r\n    it('closes the config page and confirms a successful save', async () => {\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\r\n        fireEvent.click(screen.getByRole('switch', { name: 'Startup splash' }))\r\n        fireEvent.click(screen.getByRole('button', { name: 'Save' }))\r\n\r\n        await waitFor(() => {\r\n            expect(screen.queryByRole('heading', { name: 'Config' })).toBeNull()\r\n            expect(screen.getByRole('alert')).toHaveTextContent('Config saved')\r\n        })\r\n        expect(window.location.hash).toBe('')\r\n        expect(configService.get('react.showStartupSplash')).toBe(false)\r\n    })\r\n\r\n    it('opens the config page directly from the URL', () => {\r\n        window.location.hash = '#/config/desktop'\r\n        mockMatchMedia(false)\r\n        renderWindow()\r\n\r\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\r\n        expect(screen.getByRole('tab', { name: 'Desktop' })).toBeInTheDocument()\r\n    })\r\n\r\n    it('populates the search query from a real agent run when the Electron bridge is available', async () => {\r\n        mockMatchMedia(false)\r\n        installAgentBridge('Beta')\r\n        renderWindow()\r\n\r\n        typeQuery('find the beta card')\r\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\r\n\r\n        await waitFor(() => expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('Beta'))\r\n    })\r\n\r\n    it('does not recreate the search RegExp agent on window re-render', () => {\r\n        mockMatchMedia(false)\r\n        installAgentBridge('Beta')\r\n        const createSearchRegexpAgent = vi.spyOn(searchRegexpAgent, 'createSearchRegexpAgent')\r\n        const { rerender } = renderWindow()\r\n\r\n        rerender(mainWindowElement({ toolbarAction: <button type=\"button\">Changed</button> }))\r\n\r\n        expect(createSearchRegexpAgent).toHaveBeenCalledTimes(1)\r\n    })\r\n\r\n    it('reports the RegExp agent as unavailable without the Electron bridge', async () => {\r\n        mockMatchMedia(false)\r\n        delete window.md2Actions\r\n        renderWindow()\r\n\r\n        typeQuery('alpha only')\r\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\r\n\r\n        await waitFor(() => expect(screen.getByText('RegExp agent is not available')).toBeInTheDocument())\r\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('alpha only')\r\n    })\r\n})\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:136:          "content": "---\r\nid: B-031\r\ntitle: components read mutable service state during render instead of subscribing\r\nstatus: ready\r\nowner: JB\r\naffects:\r\npolicy:\r\n  checkLinting: true\r\n  requireTests: true\r\ninternalId: 08666f38-1a4c-4c12-b2d1-12c704f22414\r\n---\r\n\r\n## Problem\r\nB-016 removed service *initialization* from render, but reading mutable service state during render remains in several components:\r\n\r\n- `ProjectWorkspace` (`app/src/components/project_workspace.tsx`) calls `dataService.getConfig()` in the render body and keeps a `configRevision` counter â€” incremented from a `configService` `changed` listener and consumed as `void configRevision` â€” purely to force a re-render so the next render re-reads the service. This is a hand-rolled, easy-to-break substitute for a subscription.\r\n- `AppMenu` (`app/src/components/shell/menu/app_menu.tsx`) calls `dataService.getConfig()` in render and seeds `useState` from `configService.get('desktop.agent'/'desktop.model')`, so a config change made elsewhere (config page save, another menu instance) does not refresh the menu until remount.\r\n- `ActionPopup` reads `configService` in `useState` initializers with an `isInitialized()` escape hatch (`readDefaultAgentSelection`), same staleness pattern.\r\n\r\nUnder React StrictMode/concurrent rendering these reads are tolerated only because the services never notify mid-render; the pattern invites tearing and stale UI.\r\n\r\n## Fix\r\n- Add hooks in `app/src/components/hooks/`:\r\n  - `useProjectConfig()` â€” `useSyncExternalStore` over `dataService` `changed` events returning `dataService.getConfig()`;\r\n  - `useConfigValue(key)` (or `useConfigValues(keys)`) â€” `useSyncExternalStore` over `configService` `changed` events.\r\n- Replace the direct render-body reads in `ProjectWorkspace`, `AppMenu` and `ActionPopup` with these hooks; delete the `configRevision` counter and its listener effect.\r\n- `AppMenu` derives selected agent/model from the hook values; local `useState` remains only for in-flight edits that have not been written to the service yet.\r\n\r\n## acceptance criteria\r\n- Saving a config change on `/config` immediately updates the app menu's agent/model selection and any open action popup defaults without remounting.\r\n- `ProjectWorkspace` re-renders on project-config changes without the revision-counter hack (`void configRevision` is gone).\r\n- No component calls `configService.get`/`dataService.getConfig` in a render body outside the shared hooks (grep-verifiable).\r\n- Tests cover hook subscription behavior (value updates on service `changed`) and the menu refresh case.\r\n\r\n## see also\r\n- `design\\feature_descriptions\\B_016_config_init_during_render.md`\r\n- `design\\feature_descriptions\\F_016_config.md`\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:288:          "content": "import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\nimport {\n    DEFAULT_CARD_TYPES,\n    DEFAULT_ACTIONS_FOLDER,\n    DEFAULT_ARCHIVED_FOLDER,\n    DEFAULT_PROJECT_FOLDER,\n    DEFAULT_RELEASES_FOLDER,\n    DEFAULT_STATES,\n    defaultColumnAccent,\n} from '../data/data_types'\nimport { dataService } from '../services/data/data_service'\nimport { dialogService } from '../services/dialog_service'\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\nimport { openFilesService } from '../services/open_files_service'\nimport type { OpenDocument } from '../services/open_files_service'\nimport { telemetryService } from '../services/telemetry/telemetry_service'\nimport { workspaceViewService } from '../services/project/workspace_view_service'\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\nimport { CardView } from './card_view/card_view'\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\nimport { useProjectReference } from './hooks/use_project_reference'\nimport { TextView } from './text_view/text_view'\nimport { FileTreeView } from './text_view/file_tree_view'\nimport { useProjectConfig } from './hooks/use_project_config'\nimport { useWorkingFolder } from './hooks/use_working_folder'\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\nimport { MobileLayout } from './shell/mobile_layout'\nimport { MobileMainWindow } from './shell/mobile_main_window'\nimport { SplitLayout } from './shell/split_layout'\n\nconst WORKSPACE_PANEL_PADDING = 3\n\nfunction openDocumentPath(document: OpenDocument) {\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\n}\n\nfunction flushPendingCommits() {\n    flushMarkdownEditors()\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\n    })\n}\n\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\n    try {\n        flushMarkdownEditors()\n        await projectPersistenceService.flushPendingChanges()\n        lifecycleBridge.confirmFlush(requestId)\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\n    }\n}\n\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\n    try {\n        action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\ninterface ProjectWorkspaceProps {\n    auth: UseGithubAuthResult\n    isMenuOpen: boolean\n    onLeftPanelInteraction: () => void\n}\n\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\n    const theme = useTheme()\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\n    const project = useProjectReference()\n    const projectConfig = useProjectConfig()\n    const workingFolder = useWorkingFolder()\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\n    const states = projectConfig?.states ?? DEFAULT_STATES\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\n    const statusColors = useMemo(() => new Map(\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\n    ), [states])\n\n    useEffect(() => {\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\n    })\n\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createFolder(parentDirectory, name)\n    }, [])\n\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createMarkdownFile(parentDirectory, name)\n    }, [])\n\n    const handleDeleteFile = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFile(path)\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\n            if (document) openFilesService.closeDocument(document)\n            workspaceViewService.clearSelectedPath(path)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFolder = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFolder(path)\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\n            const documents = openFilesService.getSnapshot().documents\n            for (const document of documents) {\n                const openPath = openDocumentPath(document)\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\n            }\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    useEffect(() => {\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\n            flushMarkdownEditors()\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\n            // quit instead, so only prompt in a plain browser build.\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\n                event.preventDefault()\n                event.returnValue = ''\n            }\n\n            flushPendingCommits()\n        }\n\n        const handleVisibilityChange = () => {\n            if (document.visibilityState === 'hidden') flushPendingCommits()\n        }\n\n        const handleBlur = () => {\n            flushMarkdownEditors()\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\n        }\n\n        document.addEventListener('visibilitychange', handleVisibilityChange)\n        window.addEventListener('beforeunload', handleBeforeUnload)\n        window.addEventListener('blur', handleBlur)\n\n        return () => {\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\n            window.removeEventListener('beforeunload', handleBeforeUnload)\n            window.removeEventListener('blur', handleBlur)\n        }\n    }, [])\n\n    useEffect(() => {\n        const lifecycleBridge = getElectronLifecycleBridge()\n        if (!lifecycleBridge) return undefined\n\n        return lifecycleBridge.onFlushRequested((requestId) => {\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\n        })\n    }, [])\n\n    useEffect(() => {\n        const handleNavigationOpen = (event: Event) => {\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\n            // Reveal the card/file without changing the current view mode: highlight it in card view\n            // and open it in the service-owned text-view tabs.\n            workspaceViewService.selectPath(path)\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n            telemetryService.trackEvent('navigation')\n        }\n\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\n\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\n    }, [])\n\n    const fileTree = (\n        <Box\n            aria-label=\"File tree\"\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\n        >\n            <FileTreeView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                onCreateFolder={handleCreateFolder}\n                onCreateMarkdownFile={handleCreateMarkdownFile}\n                onDeleteFile={handleDeleteFile}\n                onDeleteFolder={handleDeleteFolder}\n                onLeftPanelInteraction={onLeftPanelInteraction}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                statusColors={statusColors}\n                workingFolder={workingFolder}\n            />\n        </Box>\n    )\n    const textView = (\n        <Paper\n            elevation={0}\n            sx={{\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: 2,\n                boxSizing: 'border-box',\n                display: 'flex',\n                height: '100%',\n                minHeight: 0,\n                overflow: 'hidden',\n                p: WORKSPACE_PANEL_PADDING,\n            }}\n        >\n            <TextView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                states={states}\n            />\n        </Paper>\n    )\n    const views = (\n        <>\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\n            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />\n        </>\n    )\n    const workspace = (\n        <ProjectWorkspaceAvailability>\n            {views}\n        </ProjectWorkspaceAvailability>\n    )\n    const navigation = project ? fileTree : (\n        <Box sx={{ p: 2 }}>\n            <Typography color=\"text.secondary\" variant=\"body2\">\n                No project navigation available.\n            </Typography>\n        </Box>\n    )\n\n    return (\n        <Box\n            aria-label=\"Project workspace\"\n            component=\"section\"\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            {isMobile ? (\n                <MobileMainWindow\n                    auth={auth}\n                    isMenuOpen={isMenuOpen}\n                    leftPanel={navigation}\n                    onCloseMenu={onLeftPanelInteraction}\n                    rightPanel={workspace}\n                    showNavigationInCards={!project}\n                />\n            ) : workspace}\n        </Box>\n    )\n}\n\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:306:          "content": "import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { within } from '@testing-library/react'\nimport type { UseGithubAuthResult } from '../../auth/use_github_auth'\nimport type { ElectronActionBridge } from '../../data/electron_action_bridge'\nimport type { MarkdownFile, StorageService } from '../../data/data_types'\nimport { configService } from '../../services/config/config_service'\nimport { actionService } from '../../services/actions/action_service'\nimport { dataService } from '../../services/data/data_service'\nimport { projectPersistenceService } from '../../services/project/project_persistence_service'\nimport { openFilesService } from '../../services/open_files_service'\nimport * as searchRegexpAgent from '../../services/search/search_regexp_agent'\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\nimport { AppThemeProvider } from '../../theme/theme_provider'\nimport { DialogDisplay } from '../dialog_display'\nimport { MainWindow } from './main_window'\n\nconst auth: UseGithubAuthResult = {\n    accessToken: null,\n    errorMessage: null,\n    isAuthenticated: false,\n    isLoadingUser: false,\n    logout: vi.fn(),\n    savePersonalAccessToken: vi.fn(),\n    status: 'idle',\n    user: null,\n}\n\nfunction mainWindowElement(overrides?: Partial<Parameters<typeof MainWindow>[0]>) {\n    return (\n        <AppThemeProvider>\n            <DialogDisplay />\n            <MainWindow\n                auth={auth}\n                toolbarAction={<button type=\"button\">Action</button>}\n                {...overrides}\n            />\n        </AppThemeProvider>\n    )\n}\n\nfunction renderWindow(overrides?: Partial<Parameters<typeof MainWindow>[0]>) {\n    return render(mainWindowElement(overrides))\n}\n\nfunction installAgentBridge(stdout: string) {\n    const bridge: ElectronActionBridge = {\n        cancelActionExecution: vi.fn(async () => {}),\n        generateDiff: vi.fn(async () => ({ commit: '', files: [] })),\n        loadActionRunHistory: vi.fn(async () => []),\n        onActionExecution: vi.fn(() => () => {}),\n        openInEditor: vi.fn(async () => {}),\n        prepareActionPrompt: vi.fn(async () => ({ prompt: '' })),\n        runSearchRegexpAgent: vi.fn(async () => stdout),\n        startAction: vi.fn(async () => 'action-1'),\n    }\n    window.md2Actions = bridge\n\n    return bridge\n}\n\nfunction createStorage(files: MarkdownFile[] = []): StorageService {\n    return {\n        checkoutBranch: vi.fn(async (project, branch) => ({ ...project, branch })),\n        commit: vi.fn(async () => []),\n        createProject: vi.fn(async (project) => project),\n        deleteFile: vi.fn(),\n        deleteFolder: vi.fn(),\n        listBranches: vi.fn(async () => []),\n        listRepositories: vi.fn(async () => []),\n        listRepositoryFiles: vi.fn(async () => []),\n        listTopLevelFolders: vi.fn(async () => []),\n        loadActionFiles: vi.fn(async () => []),\n        loadProject: vi.fn(async () => ({ files, workingFolder: 'design' })),\n        loadProjectRoot: vi.fn(async () => ({ files, workingFolder: 'design' })),\n        loadProjectConfig: vi.fn(async () => ({ backgroundShade: 'blue' as const, projectFolder: '', workingFolder: 'design' })),\n        moveFiles: vi.fn(),\n        push: vi.fn(),\n        saveProjectConfig: vi.fn(),\n    }\n}\n\nasync function openProjectWithCards() {\n    const files = [\n        { content: '---\\nid: F-1\\ntitle: Root\\nstatus: active\\naffects:\\n---\\n\\n# Root', path: 'design/F-1-root.md' },\n        { content: '# Old', path: 'design/history/F-2-old.md' },\n    ]\n    openFilesService.init({ actionService, dataService })\n    projectPersistenceService.init({ actionService, dataService, openFilesService })\n    dataService.init({ storage: createStorage(files) })\n    const project = { branch: 'main', id: 'project', rootPath: 'C:/project' }\n    const snapshot = await dataService.projectLoading.openProject(project)\n\n    return { project, snapshot, storageType: 'local' as const }\n}\n\nfunction typeQuery(value: string) {\n    fireEvent.focus(screen.getByRole('textbox', { name: 'Search project' }))\n    fireEvent.change(screen.getByRole('textbox', { name: 'Search project' }), { target: { value } })\n}\n\nfunction mockMatchMedia(matches: boolean) {\n    window.matchMedia = ((query: string) => ({\n        addEventListener: () => {},\n        addListener: () => {},\n        dispatchEvent: () => false,\n        matches,\n        media: query,\n        onchange: null,\n        removeEventListener: () => {},\n        removeListener: () => {},\n    })) as unknown as typeof window.matchMedia\n}\n\ndescribe('MainWindow', () => {\n    beforeEach(() => {\n        configService.init({ desktopConfig: null })\n        openFilesService.init({ actionService, dataService })\n        projectPersistenceService.init({ actionService, dataService, openFilesService })\n        dataService.init({ storage: createStorage() })\n    })\n\n    afterEach(() => {\n        cleanup()\n        dataService.init({ storage: createStorage() })\n        configService.clear()\n        delete window.md2Actions\n        window.location.hash = ''\n        workspaceViewService.setViewMode('cards')\n        mockMatchMedia(false)\n    })\n\n    it('shows the workspace and status bar on desktop', () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Open project' })).toBeInTheDocument()\n        expect(screen.getByRole('heading', { name: 'No project open' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()\n        expect(screen.queryByRole('button', { name: 'Open menu' })).toBeNull()\n    })\n\n    it('shows card columns without a left navigation panel in card view', async () => {\n        mockMatchMedia(false)\n        await openProjectWithCards()\n        renderWindow()\n\n        expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\n        expect(within(screen.getByLabelText('Card columns')).getByText('Root')).toBeInTheDocument()\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('2cards')\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('1active')\n        expect(screen.queryByText('No project navigation available.')).toBeNull()\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\n        expect(screen.getByLabelText('File tree')).not.toBeVisible()\n    })\n\n    it('keeps text navigation hidden when the first project opens in card view', async () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\n\n        await openProjectWithCards()\n\n        await waitFor(() => {\n            expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\n            expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\n            expect(screen.getByLabelText('File tree')).not.toBeVisible()\n        })\n    })\n\n    it('switches from card view to text view on desktop without resetting back to cards', async () => {\n        mockMatchMedia(false)\n        await openProjectWithCards()\n        renderWindow()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\n\n        expect(await screen.findByLabelText('File tree')).toBeInTheDocument()\n        expect(screen.queryByRole('heading', { name: 'Files' })).toBeNull()\n        expect(screen.getByRole('separator', { name: 'Resize panels' })).toBeInTheDocument()\n    })\n\n    it('keeps the project workspace mounted while switching desktop views', async () => {\n        mockMatchMedia(false)\n        await openProjectWithCards()\n        renderWindow()\n        const workspace = screen.getByLabelText('Project workspace')\n\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\n        await screen.findByLabelText('File tree')\n\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\n\n        fireEvent.click(screen.getByRole('button', { name: 'Cards view' }))\n\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\n    })\n\n    it('moves the left panel content into a hamburger drawer on mobile', () => {\n        mockMatchMedia(true)\n        renderWindow()\n\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\n        expect(screen.queryByRole('button', { name: /Switch to (dark|light) theme/ })).toBeNull()\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\n        expect(screen.getByText('No project navigation available.')).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\n    })\n\n    it('opens mobile search from a toolbar icon', () => {\n        mockMatchMedia(true)\n        renderWindow()\n\n        expect(screen.queryByRole('textbox', { name: 'Search project' })).toBeNull()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Search' }))\n\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveFocus()\n    })\n\n    it('keeps GitHub authentication in the mobile drawer footer', () => {\n        mockMatchMedia(true)\n        renderWindow()\n\n        expect(screen.queryByRole('button', { name: 'GitHub account' })).toBeNull()\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\n        const drawerFooter = screen.getByRole('contentinfo')\n        fireEvent.click(within(drawerFooter).getByRole('button', { name: 'GitHub account' }))\n\n        expect(screen.getByLabelText('Personal access token')).toBeInTheDocument()\n    })\n\n    it('opens the config page from the toolbar', () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\n\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\n        expect(window.location.hash).toBe('#/config')\n    })\n\n    it('closes the config page and confirms a successful save', async () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\n        fireEvent.click(screen.getByRole('switch', { name: 'Startup splash' }))\n        fireEvent.click(screen.getByRole('button', { name: 'Save' }))\n\n        await waitFor(() => {\n            expect(screen.queryByRole('heading', { name: 'Config' })).toBeNull()\n            expect(screen.getByRole('alert')).toHaveTextContent('Config saved')\n        })\n        expect(window.location.hash).toBe('')\n        expect(configService.get('react.showStartupSplash')).toBe(false)\n    })\n\n    it('opens the config page directly from the URL', () => {\n        window.location.hash = '#/config/desktop'\n        mockMatchMedia(false)\n        renderWindow()\n\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\n        expect(screen.getByRole('tab', { name: 'Desktop' })).toBeInTheDocument()\n    })\n\n    it('populates the search query from a real agent run when the Electron bridge is available', async () => {\n        mockMatchMedia(false)\n        installAgentBridge('Beta')\n        renderWindow()\n\n        typeQuery('find the beta card')\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\n\n        await waitFor(() => expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('Beta'))\n    })\n\n    it('does not recreate the search RegExp agent on window re-render', () => {\n        mockMatchMedia(false)\n        installAgentBridge('Beta')\n        const createSearchRegexpAgent = vi.spyOn(searchRegexpAgent, 'createSearchRegexpAgent')\n        const { rerender } = renderWindow()\n\n        rerender(mainWindowElement({ toolbarAction: <button type=\"button\">Changed</button> }))\n\n        expect(createSearchRegexpAgent).toHaveBeenCalledTimes(1)\n    })\n\n    it('reports the RegExp agent as unavailable without the Electron bridge', async () => {\n        mockMatchMedia(false)\n        delete window.md2Actions\n        renderWindow()\n\n        typeQuery('alpha only')\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\n\n        await waitFor(() => expect(screen.getByText('RegExp agent is not available')).toBeInTheDocument())\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('alpha only')\n    })\n})\n\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:324:          "content": "import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\nimport {\n    DEFAULT_CARD_TYPES,\n    DEFAULT_ACTIONS_FOLDER,\n    DEFAULT_ARCHIVED_FOLDER,\n    DEFAULT_PROJECT_FOLDER,\n    DEFAULT_RELEASES_FOLDER,\n    DEFAULT_STATES,\n    defaultColumnAccent,\n} from '../data/data_types'\nimport { dataService } from '../services/data/data_service'\nimport { dialogService } from '../services/dialog_service'\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\nimport { openFilesService } from '../services/open_files_service'\nimport type { OpenDocument } from '../services/open_files_service'\nimport { telemetryService } from '../services/telemetry/telemetry_service'\nimport { workspaceViewService } from '../services/project/workspace_view_service'\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\nimport { CardView } from './card_view/card_view'\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\nimport { useProjectReference } from './hooks/use_project_reference'\nimport { TextView } from './text_view/text_view'\nimport { FileTreeView } from './text_view/file_tree_view'\nimport { useProjectConfig } from './hooks/use_project_config'\nimport { useWorkingFolder } from './hooks/use_working_folder'\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\nimport { MobileLayout } from './shell/mobile_layout'\nimport { MobileMainWindow } from './shell/mobile_main_window'\nimport { SplitLayout } from './shell/split_layout'\n\nconst WORKSPACE_PANEL_PADDING = 3\n\nfunction openDocumentPath(document: OpenDocument) {\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\n}\n\nfunction flushPendingCommits() {\n    flushMarkdownEditors()\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\n    })\n}\n\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\n    try {\n        flushMarkdownEditors()\n        await projectPersistenceService.flushPendingChanges()\n        lifecycleBridge.confirmFlush(requestId)\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\n    }\n}\n\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\n    try {\n        action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\ninterface ProjectWorkspaceProps {\n    auth: UseGithubAuthResult\n    isMenuOpen: boolean\n    onLeftPanelInteraction: () => void\n}\n\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\n    const theme = useTheme()\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\n    const project = useProjectReference()\n    const projectConfig = useProjectConfig()\n    const workingFolder = useWorkingFolder()\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\n    const states = projectConfig?.states ?? DEFAULT_STATES\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\n    const statusColors = useMemo(() => new Map(\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\n    ), [states])\n\n    useEffect(() => {\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\n    })\n\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createFolder(parentDirectory, name)\n    }, [])\n\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createMarkdownFile(parentDirectory, name)\n    }, [])\n\n    const handleDeleteFile = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFile(path)\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\n            if (document) openFilesService.closeDocument(document)\n            workspaceViewService.clearSelectedPath(path)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFolder = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFolder(path)\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\n            const documents = openFilesService.getSnapshot().documents\n            for (const document of documents) {\n                const openPath = openDocumentPath(document)\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\n            }\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    useEffect(() => {\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\n            flushMarkdownEditors()\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\n            // quit instead, so only prompt in a plain browser build.\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\n                event.preventDefault()\n                event.returnValue = ''\n            }\n\n            flushPendingCommits()\n        }\n\n        const handleVisibilityChange = () => {\n            if (document.visibilityState === 'hidden') flushPendingCommits()\n        }\n\n        const handleBlur = () => {\n            flushMarkdownEditors()\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\n        }\n\n        document.addEventListener('visibilitychange', handleVisibilityChange)\n        window.addEventListener('beforeunload', handleBeforeUnload)\n        window.addEventListener('blur', handleBlur)\n\n        return () => {\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\n            window.removeEventListener('beforeunload', handleBeforeUnload)\n            window.removeEventListener('blur', handleBlur)\n        }\n    }, [])\n\n    useEffect(() => {\n        const lifecycleBridge = getElectronLifecycleBridge()\n        if (!lifecycleBridge) return undefined\n\n        return lifecycleBridge.onFlushRequested((requestId) => {\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\n        })\n    }, [])\n\n    useEffect(() => {\n        const handleNavigationOpen = (event: Event) => {\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\n            // Reveal the card/file without changing the current view mode: highlight it in card view\n            // and open it in the service-owned text-view tabs.\n            workspaceViewService.selectPath(path)\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n            telemetryService.trackEvent('navigation')\n        }\n\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\n\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\n    }, [])\n\n    const fileTree = (\n        <Box\n            aria-label=\"File tree\"\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\n        >\n            <FileTreeView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                onCreateFolder={handleCreateFolder}\n                onCreateMarkdownFile={handleCreateMarkdownFile}\n                onDeleteFile={handleDeleteFile}\n                onDeleteFolder={handleDeleteFolder}\n                onLeftPanelInteraction={onLeftPanelInteraction}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                statusColors={statusColors}\n                workingFolder={workingFolder}\n            />\n        </Box>\n    )\n    const textView = (\n        <Paper\n            elevation={0}\n            sx={{\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: 2,\n                boxSizing: 'border-box',\n                display: 'flex',\n                height: '100%',\n                minHeight: 0,\n                overflow: 'hidden',\n                p: WORKSPACE_PANEL_PADDING,\n            }}\n        >\n            <TextView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                states={states}\n            />\n        </Paper>\n    )\n    const views = (\n        <>\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\n            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />\n        </>\n    )\n    const workspace = (\n        <ProjectWorkspaceAvailability>\n            {views}\n        </ProjectWorkspaceAvailability>\n    )\n    const navigation = project ? fileTree : (\n        <Box sx={{ p: 2 }}>\n            <Typography color=\"text.secondary\" variant=\"body2\">\n                No project navigation available.\n            </Typography>\n        </Box>\n    )\n\n    return (\n        <Box\n            aria-label=\"Project workspace\"\n            component=\"section\"\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            {isMobile ? (\n                <MobileMainWindow\n                    auth={auth}\n                    isMenuOpen={isMenuOpen}\n                    leftPanel={navigation}\n                    onCloseMenu={onLeftPanelInteraction}\n                    rightPanel={workspace}\n                    showNavigationInCards={!project}\n                />\n            ) : workspace}\n        </Box>\n    )\n}\n\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:489:          "content": "import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { within } from '@testing-library/react'\nimport type { UseGithubAuthResult } from '../../auth/use_github_auth'\nimport type { ElectronActionBridge } from '../../data/electron_action_bridge'\nimport type { MarkdownFile, StorageService } from '../../data/data_types'\nimport { configService } from '../../services/config/config_service'\nimport { actionService } from '../../services/actions/action_service'\nimport { dataService } from '../../services/data/data_service'\nimport { projectPersistenceService } from '../../services/project/project_persistence_service'\nimport { openFilesService } from '../../services/open_files_service'\nimport * as searchRegexpAgent from '../../services/search/search_regexp_agent'\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\nimport { AppThemeProvider } from '../../theme/theme_provider'\nimport { DialogDisplay } from '../dialog_display'\nimport { MainWindow } from './main_window'\n\nconst auth: UseGithubAuthResult = {\n    accessToken: null,\n    errorMessage: null,\n    isAuthenticated: false,\n    isLoadingUser: false,\n    logout: vi.fn(),\n    savePersonalAccessToken: vi.fn(),\n    status: 'idle',\n    user: null,\n}\n\nfunction mainWindowElement(overrides?: Partial<Parameters<typeof MainWindow>[0]>) {\n    return (\n        <AppThemeProvider>\n            <DialogDisplay />\n            <MainWindow\n                auth={auth}\n                toolbarAction={<button type=\"button\">Action</button>}\n                {...overrides}\n            />\n        </AppThemeProvider>\n    )\n}\n\nfunction renderWindow(overrides?: Partial<Parameters<typeof MainWindow>[0]>) {\n    return render(mainWindowElement(overrides))\n}\n\nfunction installAgentBridge(stdout: string) {\n    const bridge: ElectronActionBridge = {\n        cancelActionExecution: vi.fn(async () => {}),\n        generateDiff: vi.fn(async () => ({ commit: '', files: [] })),\n        loadActionRunHistory: vi.fn(async () => []),\n        onActionExecution: vi.fn(() => () => {}),\n        openInEditor: vi.fn(async () => {}),\n        prepareActionPrompt: vi.fn(async () => ({ prompt: '' })),\n        runSearchRegexpAgent: vi.fn(async () => stdout),\n        startAction: vi.fn(async () => 'action-1'),\n    }\n    window.md2Actions = bridge\n\n    return bridge\n}\n\nfunction createStorage(files: MarkdownFile[] = []): StorageService {\n    return {\n        checkoutBranch: vi.fn(async (project, branch) => ({ ...project, branch })),\n        commit: vi.fn(async () => []),\n        createProject: vi.fn(async (project) => project),\n        deleteFile: vi.fn(),\n        deleteFolder: vi.fn(),\n        listBranches: vi.fn(async () => []),\n        listRepositories: vi.fn(async () => []),\n        listRepositoryFiles: vi.fn(async () => []),\n        listTopLevelFolders: vi.fn(async () => []),\n        loadActionFiles: vi.fn(async () => []),\n        loadProject: vi.fn(async () => ({ files, workingFolder: 'design' })),\n        loadProjectRoot: vi.fn(async () => ({ files, workingFolder: 'design' })),\n        loadProjectConfig: vi.fn(async () => ({ backgroundShade: 'blue' as const, projectFolder: '', workingFolder: 'design' })),\n        moveFiles: vi.fn(),\n        push: vi.fn(),\n        saveProjectConfig: vi.fn(),\n    }\n}\n\nasync function openProjectWithCards() {\n    const files = [\n        { content: '---\\nid: F-1\\ntitle: Root\\nstatus: active\\naffects:\\n---\\n\\n# Root', path: 'design/F-1-root.md' },\n        { content: '# Old', path: 'design/history/F-2-old.md' },\n    ]\n    openFilesService.init({ actionService, dataService })\n    projectPersistenceService.init({ actionService, dataService, openFilesService })\n    dataService.init({ storage: createStorage(files) })\n    const project = { branch: 'main', id: 'project', rootPath: 'C:/project' }\n    const snapshot = await dataService.projectLoading.openProject(project)\n\n    return { project, snapshot, storageType: 'local' as const }\n}\n\nfunction typeQuery(value: string) {\n    fireEvent.focus(screen.getByRole('textbox', { name: 'Search project' }))\n    fireEvent.change(screen.getByRole('textbox', { name: 'Search project' }), { target: { value } })\n}\n\nfunction mockMatchMedia(matches: boolean) {\n    window.matchMedia = ((query: string) => ({\n        addEventListener: () => {},\n        addListener: () => {},\n        dispatchEvent: () => false,\n        matches,\n        media: query,\n        onchange: null,\n        removeEventListener: () => {},\n        removeListener: () => {},\n    })) as unknown as typeof window.matchMedia\n}\n\ndescribe('MainWindow', () => {\n    beforeEach(() => {\n        configService.init({ desktopConfig: null })\n        openFilesService.init({ actionService, dataService })\n        projectPersistenceService.init({ actionService, dataService, openFilesService })\n        dataService.init({ storage: createStorage() })\n    })\n\n    afterEach(() => {\n        cleanup()\n        dataService.init({ storage: createStorage() })\n        configService.clear()\n        delete window.md2Actions\n        window.location.hash = ''\n        workspaceViewService.setViewMode('cards')\n        mockMatchMedia(false)\n    })\n\n    it('shows the workspace and status bar on desktop', () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Open project' })).toBeInTheDocument()\n        expect(screen.getByRole('heading', { name: 'No project open' })).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()\n        expect(screen.queryByRole('button', { name: 'Open menu' })).toBeNull()\n    })\n\n    it('shows card columns without a left navigation panel in card view', async () => {\n        mockMatchMedia(false)\n        await openProjectWithCards()\n        renderWindow()\n\n        expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\n        expect(within(screen.getByLabelText('Card columns')).getByText('Root')).toBeInTheDocument()\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('2cards')\n        expect(screen.getByRole('contentinfo')).toHaveTextContent('1active')\n        expect(screen.queryByText('No project navigation available.')).toBeNull()\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\n        expect(screen.getByLabelText('File tree')).not.toBeVisible()\n    })\n\n    it('keeps text navigation hidden when the first project opens in card view', async () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\n\n        await openProjectWithCards()\n\n        await waitFor(() => {\n            expect(screen.getByLabelText('Card columns')).toHaveTextContent('active')\n            expect(screen.queryByRole('separator', { name: 'Resize panels' })).toBeNull()\n            expect(screen.getByLabelText('File tree')).not.toBeVisible()\n        })\n    })\n\n    it('switches from card view to text view on desktop without resetting back to cards', async () => {\n        mockMatchMedia(false)\n        await openProjectWithCards()\n        renderWindow()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\n\n        expect(await screen.findByLabelText('File tree')).toBeInTheDocument()\n        expect(screen.queryByRole('heading', { name: 'Files' })).toBeNull()\n        expect(screen.getByRole('separator', { name: 'Resize panels' })).toBeInTheDocument()\n    })\n\n    it('keeps the project workspace mounted while switching desktop views', async () => {\n        mockMatchMedia(false)\n        await openProjectWithCards()\n        renderWindow()\n        const workspace = screen.getByLabelText('Project workspace')\n\n        fireEvent.click(screen.getByRole('button', { name: 'Text view' }))\n        await screen.findByLabelText('File tree')\n\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\n\n        fireEvent.click(screen.getByRole('button', { name: 'Cards view' }))\n\n        expect(screen.getByLabelText('Project workspace')).toBe(workspace)\n    })\n\n    it('moves the left panel content into a hamburger drawer on mobile', () => {\n        mockMatchMedia(true)\n        renderWindow()\n\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\n        expect(screen.queryByRole('button', { name: /Switch to (dark|light) theme/ })).toBeNull()\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\n        expect(screen.getByText('No project navigation available.')).toBeInTheDocument()\n        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()\n        expect(screen.queryByLabelText('Personal access token')).toBeNull()\n    })\n\n    it('opens mobile search from a toolbar icon', () => {\n        mockMatchMedia(true)\n        renderWindow()\n\n        expect(screen.queryByRole('textbox', { name: 'Search project' })).toBeNull()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Search' }))\n\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveFocus()\n    })\n\n    it('keeps GitHub authentication in the mobile drawer footer', () => {\n        mockMatchMedia(true)\n        renderWindow()\n\n        expect(screen.queryByRole('button', { name: 'GitHub account' })).toBeNull()\n        fireEvent.click(screen.getByRole('button', { name: 'Open menu' }))\n        const drawerFooter = screen.getByRole('contentinfo')\n        fireEvent.click(within(drawerFooter).getByRole('button', { name: 'GitHub account' }))\n\n        expect(screen.getByLabelText('Personal access token')).toBeInTheDocument()\n    })\n\n    it('opens the config page from the toolbar', () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\n\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\n        expect(window.location.hash).toBe('#/config')\n    })\n\n    it('closes the config page and confirms a successful save', async () => {\n        mockMatchMedia(false)\n        renderWindow()\n\n        fireEvent.click(screen.getByRole('button', { name: 'Config' }))\n        fireEvent.click(screen.getByRole('switch', { name: 'Startup splash' }))\n        fireEvent.click(screen.getByRole('button', { name: 'Save' }))\n\n        await waitFor(() => {\n            expect(screen.queryByRole('heading', { name: 'Config' })).toBeNull()\n            expect(screen.getByRole('alert')).toHaveTextContent('Config saved')\n        })\n        expect(window.location.hash).toBe('')\n        expect(configService.get('react.showStartupSplash')).toBe(false)\n    })\n\n    it('opens the config page directly from the URL', () => {\n        window.location.hash = '#/config/desktop'\n        mockMatchMedia(false)\n        renderWindow()\n\n        expect(screen.getByRole('heading', { name: 'Config' })).toBeInTheDocument()\n        expect(screen.getByRole('tab', { name: 'Desktop' })).toBeInTheDocument()\n    })\n\n    it('populates the search query from a real agent run when the Electron bridge is available', async () => {\n        mockMatchMedia(false)\n        installAgentBridge('Beta')\n        renderWindow()\n\n        typeQuery('find the beta card')\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\n\n        await waitFor(() => expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('Beta'))\n    })\n\n    it('does not recreate the search RegExp agent on window re-render', () => {\n        mockMatchMedia(false)\n        installAgentBridge('Beta')\n        const createSearchRegexpAgent = vi.spyOn(searchRegexpAgent, 'createSearchRegexpAgent')\n        const { rerender } = renderWindow()\n\n        rerender(mainWindowElement({ toolbarAction: <button type=\"button\">Changed</button> }))\n\n        expect(createSearchRegexpAgent).toHaveBeenCalledTimes(1)\n    })\n\n    it('reports the RegExp agent as unavailable without the Electron bridge', async () => {\n        mockMatchMedia(false)\n        delete window.md2Actions\n        renderWindow()\n\n        typeQuery('alpha only')\n        fireEvent.click(screen.getByRole('button', { name: 'Ask agent to build a RegExp' }))\n\n        await waitFor(() => expect(screen.getByText('RegExp agent is not available')).toBeInTheDocument())\n        expect(screen.getByRole('textbox', { name: 'Search project' })).toHaveValue('alpha only')\n    })\n})\n\r\n",
design\activity\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:543:          "content": "import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\nimport {\n    DEFAULT_CARD_TYPES,\n    DEFAULT_ACTIONS_FOLDER,\n    DEFAULT_ARCHIVED_FOLDER,\n    DEFAULT_PROJECT_FOLDER,\n    DEFAULT_RELEASES_FOLDER,\n    DEFAULT_STATES,\n    defaultColumnAccent,\n} from '../data/data_types'\nimport { dataService } from '../services/data/data_service'\nimport { dialogService } from '../services/dialog_service'\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\nimport { openFilesService } from '../services/open_files_service'\nimport type { OpenDocument } from '../services/open_files_service'\nimport { telemetryService } from '../services/telemetry/telemetry_service'\nimport { workspaceViewService } from '../services/project/workspace_view_service'\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\nimport { CardView } from './card_view/card_view'\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\nimport { useProjectReference } from './hooks/use_project_reference'\nimport { TextView } from './text_view/text_view'\nimport { FileTreeView } from './text_view/file_tree_view'\nimport { useProjectConfig } from './hooks/use_project_config'\nimport { useWorkingFolder } from './hooks/use_working_folder'\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\nimport { MobileLayout } from './shell/mobile_layout'\nimport { MobileMainWindow } from './shell/mobile_main_window'\nimport { SplitLayout } from './shell/split_layout'\n\nconst WORKSPACE_PANEL_PADDING = 3\n\nfunction openDocumentPath(document: OpenDocument) {\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\n}\n\nfunction flushPendingCommits() {\n    flushMarkdownEditors()\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\n    })\n}\n\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\n    try {\n        flushMarkdownEditors()\n        await projectPersistenceService.flushPendingChanges()\n        lifecycleBridge.confirmFlush(requestId)\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\n    }\n}\n\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\n    try {\n        action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\ninterface ProjectWorkspaceProps {\n    auth: UseGithubAuthResult\n    isMenuOpen: boolean\n    onLeftPanelInteraction: () => void\n}\n\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\n    const theme = useTheme()\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\n    const project = useProjectReference()\n    const projectConfig = useProjectConfig()\n    const workingFolder = useWorkingFolder()\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\n    const states = projectConfig?.states ?? DEFAULT_STATES\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\n    const statusColors = useMemo(() => new Map(\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\n    ), [states])\n\n    useEffect(() => {\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\n    })\n\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createFolder(parentDirectory, name)\n    }, [])\n\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\n        await dataService.cards.createMarkdownFile(parentDirectory, name)\n    }, [])\n\n    const handleDeleteFile = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFile(path)\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\n            if (document) openFilesService.closeDocument(document)\n            workspaceViewService.clearSelectedPath(path)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFolder = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFolder(path)\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\n            const documents = openFilesService.getSnapshot().documents\n            for (const document of documents) {\n                const openPath = openDocumentPath(document)\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\n            }\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    useEffect(() => {\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\n            flushMarkdownEditors()\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\n            // quit instead, so only prompt in a plain browser build.\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\n                event.preventDefault()\n                event.returnValue = ''\n            }\n\n            flushPendingCommits()\n        }\n\n        const handleVisibilityChange = () => {\n            if (document.visibilityState === 'hidden') flushPendingCommits()\n        }\n\n        const handleBlur = () => {\n            flushMarkdownEditors()\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\n        }\n\n        document.addEventListener('visibilitychange', handleVisibilityChange)\n        window.addEventListener('beforeunload', handleBeforeUnload)\n        window.addEventListener('blur', handleBlur)\n\n        return () => {\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\n            window.removeEventListener('beforeunload', handleBeforeUnload)\n            window.removeEventListener('blur', handleBlur)\n        }\n    }, [])\n\n    useEffect(() => {\n        const lifecycleBridge = getElectronLifecycleBridge()\n        if (!lifecycleBridge) return undefined\n\n        return lifecycleBridge.onFlushRequested((requestId) => {\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\n        })\n    }, [])\n\n    useEffect(() => {\n        const handleNavigationOpen = (event: Event) => {\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\n            // Reveal the card/file without changing the current view mode: highlight it in card view\n            // and open it in the service-owned text-view tabs.\n            workspaceViewService.selectPath(path)\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n            telemetryService.trackEvent('navigation')\n        }\n\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\n\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\n    }, [])\n\n    const fileTree = (\n        <Box\n            aria-label=\"File tree\"\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\n        >\n            <FileTreeView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                onCreateFolder={handleCreateFolder}\n                onCreateMarkdownFile={handleCreateMarkdownFile}\n                onDeleteFile={handleDeleteFile}\n                onDeleteFolder={handleDeleteFolder}\n                onLeftPanelInteraction={onLeftPanelInteraction}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                statusColors={statusColors}\n                workingFolder={workingFolder}\n            />\n        </Box>\n    )\n    const textView = (\n        <Paper\n            elevation={0}\n            sx={{\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: 2,\n                boxSizing: 'border-box',\n                display: 'flex',\n                height: '100%',\n                minHeight: 0,\n                overflow: 'hidden',\n                p: WORKSPACE_PANEL_PADDING,\n            }}\n        >\n            <TextView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                states={states}\n            />\n        </Paper>\n    )\n    const views = (\n        <>\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\n            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />\n        </>\n    )\n    const workspace = (\n        <ProjectWorkspaceAvailability>\n            {views}\n        </ProjectWorkspaceAvailability>\n    )\n    const navigation = project ? fileTree : (\n        <Box sx={{ p: 2 }}>\n            <Typography color=\"text.secondary\" variant=\"body2\">\n                No project navigation available.\n            </Typography>\n        </Box>\n    )\n\n    return (\n        <Box\n            aria-label=\"Project workspace\"\n            component=\"section\"\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            {isMobile ? (\n                <MobileMainWindow\n                    auth={auth}\n                    isMenuOpen={isMenuOpen}\n                    leftPanel={navigation}\n                    onCloseMenu={onLeftPanelInteraction}\n                    rightPanel={workspace}\n                    showNavigationInCards={!project}\n                />\n            ) : workspace}\n        </Box>\n    )\n}\n\r\n",
