design\activity\card__3e151ae1-ffa3-42ba-819c-a6973683af03.json:46:          "content": "import { Box } from '@mui/material'\nimport { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'\nimport type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'\nimport { useCallback, useEffect, useRef, useState } from 'react'\nimport { buildCardColumns } from '../../data/card_ordering'\nimport type { CardTypeConfig, StateConfig } from '../../data/data_types'\nimport { useAgentAcknowledgements } from '../hooks/use_agent_acknowledgements'\nimport { dataService } from '../../services/data/data_service'\nimport { dialogService } from '../../services/dialog_service'\nimport { openFilesService } from '../../services/open_files_service'\nimport { workspaceViewService } from '../../services/project/workspace_view_service'\nimport { telemetryService } from '../../services/telemetry/telemetry_service'\nimport { AffectsEditorDialog } from './affects_editor_dialog'\nimport { CardActionPopupHost } from '../actions/card_action_popup_host'\nimport { CardBodyPopover } from './card_body_popover'\nimport { cardBodyPopoverService } from './card_body_popover_service'\nimport { CardColumn } from './card_column'\nimport { CardDragOverlay } from './card_drag_overlay'\nimport { cardDragDropService } from './card_drag_drop_service'\nimport { resolveCardDragEvent, type CardVerticalBounds } from './card_drag'\nimport { useCardViewColumns } from './use_card_view_columns'\n\nconst DRAG_ACTIVATION_DISTANCE = 2\ninterface CardViewProps {\n    cardTypes: CardTypeConfig[]\n    isMobile: boolean\n    states: StateConfig[]\n}\n\nasync function runCardEdit(action: () => unknown, fallbackMessage: string) {\n    try {\n        await action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\nfunction measureCardVerticalBounds(): Map<string, CardVerticalBounds> {\n    const boundsByPath = new Map<string, CardVerticalBounds>()\n    const cardElements = document.querySelectorAll<HTMLElement>('[data-card-path]')\n    for (const cardElement of cardElements) {\n        const path = cardElement.dataset.cardPath\n        if (!path) throw new Error('Card element is missing its path')\n\n        const { height, top } = cardElement.getBoundingClientRect()\n        boundsByPath.set(path, { height, top })\n    }\n\n    return boundsByPath\n}\n\nfunction currentCardColumns(states: StateConfig[]) {\n    const cards = dataService.getState().snapshot?.activeCards ?? []\n\n    return buildCardColumns(cards, states)\n}\n\n/** Card view: status columns of draggable cards with card-anchored body popup access. */\nexport function CardView(props: CardViewProps) {\n    const {\n        cardTypes,\n        isMobile,\n        states,\n    } = props\n    useAgentAcknowledgements()\n    const columns = useCardViewColumns(states)\n    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)\n    const initialCardBoundsRef = useRef(new Map<string, CardVerticalBounds>())\n    const rootElementRef = useRef<HTMLDivElement>(null)\n    const wasVisibleRef = useRef<boolean | null>(null)\n    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE } }))\n\n    const handleOpenAffects = (path: string) => {\n        setOpenAffectsPath(path)\n    }\n\n    const handleCloseAffects = () => {\n        setOpenAffectsPath(null)\n    }\n\n    const clearActiveCard = useCallback(() => {\n        cardDragDropService.endDrag()\n        initialCardBoundsRef.current.clear()\n    }, [])\n\n    useEffect(() => {\n        const updateVisibility = () => {\n            const rootElement = rootElementRef.current\n            if (!rootElement) throw new Error('Missing card view root element')\n\n            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'\n            rootElement.style.display = isVisible ? 'flex' : 'none'\n            if (wasVisibleRef.current === isVisible) return\n\n            wasVisibleRef.current = isVisible\n            if (isVisible) return\n\n            queueMicrotask(() => {\n                cardBodyPopoverService.close()\n                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)\n                clearActiveCard()\n            })\n        }\n\n        updateVisibility()\n        workspaceViewService.addEventListener('changed', updateVisibility)\n\n        return () => workspaceViewService.removeEventListener('changed', updateVisibility)\n    }, [clearActiveCard])\n\n    useEffect(() => () => cardBodyPopoverService.close(), [])\n\n    const handleDragStart = useCallback((event: DragStartEvent) => {\n        initialCardBoundsRef.current = measureCardVerticalBounds()\n        cardDragDropService.startDrag(\n            String(event.active.id),\n            event.active.rect.current.initial?.height ?? null,\n            event.active.rect.current.initial?.width ?? null,\n        )\n    }, [])\n\n    const handleDragMove = useCallback((event: DragMoveEvent) => {\n        const { active, over } = event\n        if (!over) {\n            cardDragDropService.setDropPreview(null)\n            return\n        }\n\n        const dragColumns = currentCardColumns(states)\n        const drop = resolveCardDragEvent(dragColumns, event, initialCardBoundsRef.current)\n        const sourceColumn = dragColumns.find((column) => column.cards.some((card) => card.path === String(active.id)))\n        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null\n        cardDragDropService.setDropPreview(dropPreview)\n    }, [states])\n\n    const handleDragEnd = useCallback((event: DragEndEvent) => {\n        const { active, over } = event\n        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event, initialCardBoundsRef.current) : null\n        clearActiveCard()\n        const path = String(active.id)\n        if (drop) void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)\n    }, [clearActiveCard, states])\n\n    const handleOpenInFileMode = (path: string) => {\n        cardBodyPopoverService.close()\n        workspaceViewService.selectPath(path)\n        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n        workspaceViewService.setViewMode('text')\n        telemetryService.trackEvent('navigation')\n    }\n\n    const handleDeleteCard = async (path: string) => {\n        try {\n            await dataService.cards.deleteCard(path)\n            workspaceViewService.clearSelectedPath(path)\n            cardBodyPopoverService.closePath(path)\n            if (openAffectsPath === path) handleCloseAffects()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })\n            throw error\n        }\n    }\n\n    const handleTitleChange = (path: string, title: string) => {\n        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {\n            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })\n        })\n    }\n\n    const handleTogglePolicy = (path: string, policyKey: string) => {\n        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)\n    }\n\n    const handleAffectsChange = (path: string, affects: string[]) => {\n        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)\n    }\n\n    return (\n        <Box\n            ref={rootElementRef}\n            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            <DndContext\n                collisionDetection={closestCorners}\n                onDragCancel={clearActiveCard}\n                onDragEnd={handleDragEnd}\n                onDragMove={handleDragMove}\n                onDragStart={handleDragStart}\n                sensors={sensors}\n            >\n                <Box\n                    aria-label=\"Card columns\"\n                    sx={{\n                        alignItems: 'flex-start',\n                        display: 'flex',\n                        flex: 1,\n                        flexDirection: isMobile ? 'column' : 'row',\n                        gap: 2,\n                        height: '100%',\n                        overflowX: isMobile ? 'hidden' : 'auto',\n                        overflowY: 'auto',\n                        p: 2.5,\n                    }}\n                >\n                    {columns.map((column) => (\n                        <CardColumn\n                            key={column.status}\n                            cardTypes={cardTypes}\n                            column={column}\n                            isMobile={isMobile}\n                            onDeleteCard={handleDeleteCard}\n                            onOpenInFileMode={handleOpenInFileMode}\n                            onTitleChange={handleTitleChange}\n                            onTogglePolicy={handleTogglePolicy}\n                        />\n                    ))}\n                </Box>\n                <DragOverlay>\n                    <CardDragOverlay cardTypes={cardTypes} />\n                </DragOverlay>\n                <CardBodyPopover\n                    isMobile={isMobile}\n                    onDeleteCard={handleDeleteCard}\n                    onOpenAffects={handleOpenAffects}\n                    onOpenInFileMode={handleOpenInFileMode}\n                    visible\n                />\n                <AffectsEditorDialog\n                    cardPath={openAffectsPath}\n                    onClose={handleCloseAffects}\n                    onSave={handleAffectsChange}\n                />\n                <CardActionPopupHost />\n            </DndContext>\n        </Box>\n    )\n}\n\r\nimport { cleanup, fireEvent, render, screen } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport { AppThemeProvider } from '../../theme/theme_provider'\nimport { cardMarkdownDataSource } from '../editor/card_markdown_data_source'\nimport { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'\nimport type { MarkdownDocumentTarget } from '../editor/markdown_data_source'\nimport { CardBodyEditor } from './card_body_editor'\n\nfunction renderCardBodyEditor(props: Parameters<typeof CardBodyEditor>[0]) {\n    return render(\n        <AppThemeProvider>\n            <CardBodyEditor {...props} />\n        </AppThemeProvider>,\n    )\n}\n\nfunction editorProps(overrides: Partial<Parameters<typeof CardBodyEditor>[0]> = {}): Parameters<typeof CardBodyEditor>[0] {\n    return {\n        historyStore: new MarkdownDocumentHistoryStore(),\n        isFullscreen: false,\n        onToggleFullscreen: vi.fn(),\n        ...overrides,\n    }\n}\n\ndescribe('CardBodyEditor', () => {\n    const target = { document: { kind: 'card' } } as MarkdownDocumentTarget\n\n    beforeEach(() => {\n        cardMarkdownDataSource.setActiveTarget('board-card', target)\n        vi.spyOn(cardMarkdownDataSource, 'getMarkdown').mockReturnValue('# Alpha\\n\\nOriginal body')\n        vi.spyOn(cardMarkdownDataSource, 'edit').mockImplementation(() => undefined)\n        vi.spyOn(cardMarkdownDataSource, 'commit').mockReturnValue(true)\n    })\n\n    afterEach(() => {\n        cleanup()\n        cardMarkdownDataSource.setActiveTarget('board-card', null)\n        vi.restoreAllMocks()\n    })\n\n    it('loads body through board-card data source binding', () => {\n        renderCardBodyEditor(editorProps())\n\n        expect(screen.getByRole('textbox')).toHaveValue('# Alpha\\n\\nOriginal body')\n        expect(cardMarkdownDataSource.getMarkdown).toHaveBeenCalledWith(target)\n    })\n\n    it('commits outgoing document target when editor unmounts', () => {\n        const { unmount } = renderCardBodyEditor(editorProps())\n        fireEvent.change(screen.getByRole('textbox'), { target: { value: '# Alpha\\n\\nEdited body' } })\n\n        unmount()\n\n        expect(cardMarkdownDataSource.commit).toHaveBeenCalledWith('board-card', target, '# Alpha\\n\\nEdited body')\n    })\n\n    it('keeps toolbar sticky on mobile', () => {\n        const { container } = renderCardBodyEditor(editorProps({ isMobile: true }))\n\n        expect(container.querySelector('[data-sticky-toolbar=\"true\"]')).not.toBeNull()\n    })\n})\n\r\nimport { cleanup, fireEvent, render, screen } from '@testing-library/react'\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'\nimport type { ProjectCard } from '../../data/data_types'\nimport { openFilesService } from '../../services/open_files_service'\nimport { AppThemeProvider } from '../../theme/theme_provider'\nimport { CardBodyPopover } from './card_body_popover'\nimport { dataService } from '../../services/data/data_service'\nimport { cardBodyPopoverService } from './card_body_popover_service'\n\nvi.mock('../hooks/use_card_commits', () => ({\n    useCardCommits: () => ({\n        commits: [{\n            branch: 'main',\n            commit: 'a'.repeat(40),\n            committedAt: '2026-07-20T10:00:00.000Z',\n            deletions: 1,\n            filePaths: ['design/F-060.md'],\n            filesChanged: 1,\n            insertions: 2,\n            record: {\n                commits: [],\n                completedAt: '2026-07-20T10:00:00.000Z',\n                conversationIds: [],\n                executionId: 'execution-1',\n                history: { completedAt: '2026-07-20T10:00:00.000Z', output: '', prompt: '', status: 'completed' },\n                origin: { cardInternalId: 'card-060', kind: 'card' },\n                rootActionId: 'implement',\n                rootActionLabel: 'Implement',\n                startedAt: '2026-07-20T10:00:00.000Z',\n                status: 'completed',\n            },\n        }],\n        error: null,\n    }),\n}))\n\nvi.mock('./card_commit_diff_panel', () => ({CardCommitDiffPanel: () => <div aria-label=\"Card commit diff\" />}))\n\nvi.mock('./card_body_save_status', () => ({ CardBodySaveStatus: () => null }))\nvi.mock('./card_body_editor', () => ({ CardBodyEditor: () => <div aria-label=\"Live card editor\" /> }))\n\nconst card: ProjectCard = {\n    agentConversationErrors: [],\n    agentConversations: [],\n    content: '# Card\\n\\nBody',\n    header: {\n        affects: [], after: null, agentLogReferences: [], author: null, id: 'F-060', internalId: 'card-060',\n        owner: null, policy: {}, status: 'ready', title: 'Card', worktree: null, worktreeError: null, worktreeValue: null,\n    },\n    headerFields: {},\n    isActive: true,\n    path: 'design/F-060.md',\n}\n\nafterEach(() => {\n    cleanup()\n    cardBodyPopoverService.close()\n    vi.restoreAllMocks()\n})\n\nbeforeEach(() => {\n    vi.spyOn(dataService, 'getState').mockReturnValue({\n        project: null,\n        runningAgents: [],\n        snapshot: { activeCards: [card], backgroundCards: [], repositoryFiles: [], workingFolder: 'design' },\n    })\n})\n\ndescribe('CardBodyPopover commit diff', () => {\n    it('keeps the board document bound when refreshed card data retains its identity', () => {\n        const anchorElement = document.createElement('button')\n        document.body.append(anchorElement)\n        const openBoardDocument = vi.spyOn(openFilesService, 'openBoardDocument')\n        const closeBoardDocument = vi.spyOn(openFilesService, 'closeBoardDocument')\n        const props = {\n            isMobile: false,\n            onDeleteCard: vi.fn(async () => undefined),\n            onOpenAffects: vi.fn(),\n            onOpenInFileMode: vi.fn(),\n            visible: true,\n        }\n        cardBodyPopoverService.toggle(card.path, anchorElement)\n        const view = render(\n            <AppThemeProvider>\n                <CardBodyPopover {...props} />\n            </AppThemeProvider>,\n        )\n\n        view.rerender(\n            <AppThemeProvider>\n                <CardBodyPopover {...props} />\n            </AppThemeProvider>,\n        )\n\n        expect(openBoardDocument).toHaveBeenCalledOnce()\n        expect(closeBoardDocument).not.toHaveBeenCalled()\n    })\n\n    it('uses the first Escape to exit diff and the second to close the popover', () => {\n        const anchorElement = document.createElement('button')\n        document.body.append(anchorElement)\n        cardBodyPopoverService.toggle(card.path, anchorElement)\n        render(\n            <AppThemeProvider>\n                <CardBodyPopover\n                    isMobile={false}\n                    onDeleteCard={vi.fn(async () => undefined)}\n                    onOpenAffects={vi.fn()}\n                    onOpenInFileMode={vi.fn()}\n                    visible\n                />\n            </AppThemeProvider>,\n        )\n\n        fireEvent.click(screen.getByRole('button', { name: 'Card commit history' }))\n        fireEvent.click(screen.getByRole('button', { name: /Implement/ }))\n        expect(screen.getByLabelText('Card commit diff')).toBeInTheDocument()\n        expect(screen.getByLabelText('Live card editor')).toBeInTheDocument()\n        expect(screen.getByLabelText('Live card editor')).not.toBeVisible()\n        const dialog = screen.getByRole('dialog')\n\n        fireEvent.keyDown(dialog, { key: 'Escape' })\n        expect(screen.queryByLabelText('Card commit diff')).not.toBeInTheDocument()\n        expect(screen.getByLabelText('Live card editor')).toBeVisible()\n        expect(cardBodyPopoverService.getSnapshot().cardPath).toBe(card.path)\n\n        fireEvent.keyDown(dialog, { key: 'Escape' })\n        expect(cardBodyPopoverService.getSnapshot().cardPath).toBeNull()\n    })\n})\n\r\nimport { cleanup, fireEvent, render, screen } from '@testing-library/react'\nimport { afterEach, describe, expect, it, vi } from 'vitest'\nimport { ResizablePopover } from './resizable_popover'\n\ndescribe('ResizablePopover', () => {\n    afterEach(cleanup)\n\n    it('renders an anchored dialog at its initial size', () => {\n        render(\n            <ResizablePopover\n                anchorElement={document.body}\n                initialSize={{ height: 300, width: 400 }}\n                labelId=\"popup-title\"\n                onClose={vi.fn()}\n                open\n                resizeLabel=\"Resize test popup\"\n            >\n                <h2 id=\"popup-title\">Test popup</h2>\n            </ResizablePopover>,\n        )\n\n        expect(screen.getByRole('dialog', { name: 'Test popup' })).toBeInTheDocument()\n        const paper = document.querySelector('.MuiPopover-paper') as HTMLElement\n        expect(paper.style.width).toBe('400px')\n        expect(paper.style.height).toBe('300px')\n    })\n\n    it('resizes from the configured lower corner', () => {\n        render(\n            <ResizablePopover\n                anchorElement={document.body}\n                initialSize={{ height: 300, width: 400 }}\n                labelId=\"popup-title\"\n                onClose={vi.fn()}\n                open\n                resizeCorner=\"lower-left\"\n                resizeLabel=\"Resize test popup\"\n            >\n                <h2 id=\"popup-title\">Test popup</h2>\n            </ResizablePopover>,\n        )\n        const handle = screen.getByRole('separator', { name: 'Resize test popup' })\n        const paper = document.querySelector('.MuiPopover-paper') as HTMLElement\n\n        fireEvent.pointerDown(handle, { clientX: 100, clientY: 100, pointerId: 1 })\n        fireEvent.pointerMove(window, { clientX: 50, clientY: 150, pointerId: 1 })\n        fireEvent.pointerUp(window, { pointerId: 1 })\n\n        expect(handle).toHaveAttribute('data-corner', 'lower-left')\n        expect(paper.style.width).toBe('450px')\n        expect(paper.style.height).toBe('350px')\n    })\n})\n\r\n",
design\activity\card__3e151ae1-ffa3-42ba-819c-a6973683af03.json:52:          "content": "---\ninternalId: f2ec9e28-8064-4707-bce9-b62f24d57524\n---\n\n# App Style Guide â€” Kanban / MDÂ² (React + MUI)\n\nHow to build **any new component** so it matches the app. This is written for **Material UI v5+** components.\n\n**The theme is the source of truth.** All color, radius, base typography, and spacing units live in the single `createTheme` (defined in `GUIDANCE.md` Â§1/Â§9). This guide does **not** define colors â€” it tells you **which theme value to use for which role**, and covers the things the theme can't encode: layout, spacing/margins, borders, elevation, and component conventions.\n\n**The one rule that matters:** never write a raw hex, px radius, or magic color into a component. Read it from the theme (`theme.palette.*`, `theme.shape`, `theme.typography`, `theme.spacing`). If a component has a hardcoded hex in its `sx`/styled, it's wrong â€” that's exactly where the look drifts and where dark mode breaks.\n\n---\n\n## 1. How to consume the theme\n\n- **Colors:** `sx={{ color: 'text.secondary', bgcolor: 'background.paper', borderColor: 'divider' }}` â€” MUI resolves dotted palette paths automatically in `sx`. In `styled`/JS use the callback form: `styled(Box)(({ theme }) => ({ color: theme.palette.text.secondary }))`.\n- **Spacing:** use the 8px unit via the spacing scale â€” `sx={{ p: 2, gap: 1, mt: 1.5 }}` (`2` = 16px, `1` = 8px). Don't write `padding: '16px'`.\n- **Radius:** `borderRadius: 1` (= `theme.shape.borderRadius` = 8) and multiples; for the fixed non-8 radii see Â§4.\n- **Typography:** prefer `Typography variant=...` and `theme.typography.*` over ad-hoc `fontSize`.\n- **Custom tokens:** roles the default MUI palette doesn't cover (column/track surfaces, the strong/hover border steps, `text-3/4`, section-header color, `primary-bg` tint, status colors) must exist in the theme under a namespace (e.g. `theme.palette.custom.*`) with light + dark values. Consume them the same way â€” `bgcolor: 'custom.column'`. **Never inline their hex.** If a needed token doesn't exist yet, add it to the theme, don't hardcode it in the component.\n\n---\n\n## 2. Role â†’ theme slot\n\nPick the slot by the element's **role**, not by how it looks in one mode:\n\n| Role | Theme slot |\n|---|---|\n| App background; tinted footer/action bars | `background.default` |\n| Column & sidebar surface | `custom.column` |\n| Segmented-control / toolbar track, hover fill | `custom.track` |\n| Card, dialog, popup, input surface | `background.paper` |\n| Hairlines, resting borders | `divider` |\n| Input borders, vertical separators | `custom.borderStrong` |\n| Border on hover | `custom.borderHover` |\n| Titles, values, headings | `text.primary` |\n| Body copy, field labels | `text.secondary` |\n| Meta, captions, resting icons | `custom.text3` |\n| Muted / placeholder / disabled | `custom.text4` |\n| Uppercase section/column headers | `custom.colHead` |\n| The one CTA, selection, focus, links, icon-hover | `primary.main` |\n| Contained-button hover | `primary.dark` |\n| Selected/tinted bg, focus ring, ID-chip bg | `custom.primaryBg` |\n| Text/icon on a primary fill | `primary.contrastText` |\n| Active / saved / online dot | `success.main` |\n| Destructive action | `error.main` |\n| Status swatch dots & ID-chip tints (decorative only) | `custom.status.*` |\n\nRules: **one** `primary` per surface (the CTA/selection accent) â€” everything else is `text-*`/`divider`. Status colors are **decoration only** (dots, chip tints), never interactive color. Dark-mode brightness/tinting is handled inside the theme's two palettes, so a correctly-sloted component needs zero per-mode code.\n\n---\n\n## 3. Layout\n\n- **Full-height app:** column flex â€” menu row / ribbon / content (`flex: 1; minHeight: 0`) / status bar. Fixed bands `flexShrink: 0`.\n- **Board:** horizontal-scroll flex row, `gap: 2` (16px), page padding `p: 2.5` (20px); columns `width: 296, flexShrink: 0`, internal column flex `gap: 1`.\n- **List view:** two-pane flex row filling the space between ribbon and status bar â€” sidebar `width: 280, flexShrink: 0`, editor pane `flex: 1, minWidth: 0` (the `minWidth: 0` is required so long content ellipsizes instead of blowing out the row).\n- **Panels (sidebar, editor card, dialogs):** column flex with stacked bands (header / [toolbar] / body / footer). The **body scrolls** (`overflow-y: auto; minHeight: 0`); header and footer are `flexShrink: 0` and never scroll away.\n- **Spacer pattern:** push trailing items with `<Box sx={{ flex: 1 }} />` rather than `margin-left: auto` sprinkled around, so rows stay predictable.\n- Use flex `gap` for spacing between siblings â€” don't hand-space with per-child margins.\n\n---\n\n## 4. Spacing, margin & size conventions\n\n- **4/8px grid, via `theme.spacing`.** page padding `2.5`; between columns `2`; inside columns / between related controls `1`; dialog body gap `2â€“2.25`; field labelâ†’control gap `~0.9` (7px).\n- **Margins:** prefer padding on containers + flex `gap` over element margins. Where a floating panel needs breathing room (e.g. editor card, toolbar inside a panel), use container padding (`p: 2 / 2.5`), not margins on the children.\n- **Fixed heights (px):** menu row 44, ribbon 52, status bar 32, section header 40, tab row 40, standard button / control 34, dense icon button 26â€“28, input 42.\n- **Fixed widths (px):** column 296, sidebar 280, search 260, standard dialog 480, wide/editor dialog 760.\n- **Radius family (px):** buttons/icon-buttons 8 (small 6â€“7), inputs 9, cards 10, columns/panels 12, dialogs/popups 14, chips/pills 99, color swatches 3. `borderRadius: 1` covers the 8 case; use explicit `'9px'` etc. for the others.\n\n---\n\n## 5. Borders & elevation\n\n- **Rest = border, not shadow.** Resting surfaces: `border: '1px solid'`, `borderColor: 'divider'`. Inputs use `custom.borderStrong`. **Shadow only when floating or lifted** (hover, drag, dialogs/popovers).\n- **Separation between bands:** a single 1px `divider` hairline. Don't stack a heavy rule *and* an outline â€” one line, let background contrast do the rest. Vertical separators inside toolbars: a 20px-tall `custom.borderStrong` rule.\n- **Elevation ladder (only where floating):** card hover `0 4px 12px rgba(16,24,40,0.12)`; dragging MUI `elevation 8` + `rotate(2deg)`; contained button `0 1px 2px rgba(16,24,40,0.15)`; dialog/popup `0 24px 60px rgba(16,24,40,0.28)`; scrim `rgba(16,24,40,0.45)` + `backdropFilter: blur(2px)`.\n- Set `MuiPaper.elevation: 0` and `MuiButton.disableElevation` globally in the theme; add the shadows above explicitly where the ladder calls for it.\n- **On dark backgrounds shadows read as nothing** â€” the theme already handles this by making hover raise `borderColor` (`custom.borderHover`) instead of relying on shadow.\n\n---\n\n## 6. Typography usage\n\nDrive everything from theme variants / `theme.typography`; avoid ad-hoc `fontSize`.\n\n- Titles/values/headings â†’ `text.primary`; body & labels â†’ `text.secondary`; meta â†’ `custom.text3`.\n- **Field labels:** a plain `Typography` (12px/600, `text.secondary`) placed **above** the control â€” **never** MUI floating/outlined `TextField` labels (they clash with the app's flat-label style).\n- **Section/column headers:** `Typography variant=\"overline\"` (uppercase, `letterSpacing ~0.7px`, `fontWeight 700`, `custom.colHead`).\n- **ID chips only** use monospace; everything else is the theme's default family.\n- `button.textTransform: 'none'` and `button.fontWeight: 600` are set in the theme â€” don't re-uppercase buttons.\n\n---\n\n## 7. Interaction states\n\nConsistent across all components; all colors from the theme:\n\n- **Ghost icon button** (`IconButton`): transparent â†’ hover `bgcolor: track` (or `background.paper` on a colored panel) + `color: primary.main`. Override MUI's default circular hover tint via `sx`.\n- **Outlined button:** `divider` border, `text.secondary` â†’ hover `borderColor/color: primary.main`. Destructive: hover `borderColor: error.main` + `bgcolor: custom.dangerBg`.\n- **Contained (primary) CTA:** `primary.main` + small shadow â†’ hover `primary.dark`.\n- **Input/field focus:** `borderColor: primary.main` + `boxShadow: 0 0 0 3px` in `custom.primaryBg` (the soft halo). Unfocused hover: `borderColor: custom.borderHover`.\n- **List/tree row:** hover `bgcolor: track`; selected `bgcolor: custom.primaryBg` + title `text.primary`.\n- **Row-level actions** (delete, â‹®): hidden at rest, shown on `:hover`/`:focus-within` via **opacity** (keep in DOM so width doesn't jump).\n- **Active tab/menu item:** 2px `primary.main` bottom border + `primary.main` text.\n- Every icon-only control gets a `Tooltip` (theme sets `arrow: true`) **and** an `aria-label`.\n\n---\n\n## 8. Component conventions (MUI primitives)\n\n- **Buttons:** `Button variant=\"contained\"` = the single CTA per surface; `variant=\"outlined\"` = secondary; `variant=\"text\"` = tertiary. Icon-only â†’ `IconButton` in a `Tooltip`. Don't use `Link` or text `Button` where an action button belongs (that reproduces the old text-link look).\n- **Icons:** `@mui/icons-material` **Outlined** variants; `fontSize: 18` in 34px buttons, `16` in dense, `13â€“15` inline. Don't hand-draw SVG.\n- **ID chip:** monospace, accent text on `custom.primaryBg`/status tint, `radius 5, flexShrink: 0`.\n- **Count chip:** `background.paper` bg, 1px `divider`, radius 9â€“10, `custom.text3`.\n- **State dot:** 7â€“8px circle + `text-3` label; green (`success.main`) = active/saved/online.\n- **Search:** pill `TextField` (`borderRadius: 99`, `bgcolor: background.default`), search start-adornment, `âŒ˜K` keycap end-adornment.\n- **Select:** `size=\"small\"`, optional dot+name via `renderValue`; 42px / radius-9 frame. When a select has a tooltip, keep the tooltip available while the select is closed and explicitly hide it for the entire time the select menu is open so it cannot cover the first option.\n- **Segmented control** (view switch, formatting toolbar): `ToggleButtonGroup` on a `custom.track` background; selected segment `background.paper` + `0 1px 2px` shadow + `primary` text.\n- **Dialog / popup:** `Dialog`/`Popover` with `PaperProps` â†’ `background.paper`, 1px `divider`, radius 14, big shadow; scrim via `slotProps.backdrop` (blur + tint). Bands separated by hairlines; footer on a `background.default` bar with top hairline; actions right-aligned (outlined Cancel + contained CTA). `autoFocus` first field; submit on `Enter` (`âŒ˜/Ctrl+Enter` in a textarea); close on `Esc`/backdrop.\n- **Empty state:** dashed target â€” `1.5px dashed custom.borderStrong`, radius 10, centered icon + `custom.text4` label. No \"click to add\" placeholder blocks.\n\n---\n\n## 9. Definition of done for a new component\n\n1. Zero hardcoded hex / raw px colors â€” every value comes from `theme.palette` / `theme.shape` / `theme.spacing` / `theme.typography`.\n2. Correct roleâ†’slot mapping (Â§2); at most one `primary` CTA on the surface.\n3. Borders at rest, shadow only when floating (Â§5); bands split by a single hairline.\n4. Hover **and** focus states on every interactive element (Â§7); icon buttons have tooltip + `aria-label`.\n5. Body scrolls, header/footer pinned; `minWidth: 0` on flex children that hold long text.\n6. Toggle to dark mode and confirm nothing breaks â€” if it does, you hardcoded a color somewhere (Â§1).\n\nComponent-specific detail lives in `GUIDANCE.md` (theme definition + board/list/dialog), `CARD_POPUP_GUIDE.md`, `RUN_DIALOG_GUIDE.md`, and `SIDEBAR_ACTIONS_GUIDE.md`.\n\r\n---\ninternalId: 583d9c88-b71c-4560-92ad-3e23d33bf1d0\n---\n\n# Architectural decisions\n\nProject-wide decisions for MDÂ². The app is a Vite React web app in `app/`; `desktop/` is a separate Electron host that can load the website and expose local capabilities through preload bridges.\n\n## File naming\n\n| Decision | Rule | Rationale |\n| --- | --- | --- |\n| Code files use lowercase snake_case names. | All code files in `app/src/` and `desktop/` use lowercase words separated by underscores, for example `github_auth_service.ts`, `project_workspace.tsx`, and `local_git_service.js`. Test files keep the same base name with `.test` before the extension, for example `github_auth_service.test.ts`. Exported symbols keep normal TypeScript/JavaScript casing such as `GithubAuthService`, `ProjectWorkspace`, and `useGithubAuth`. | A single file naming convention avoids mixed PascalCase, camelCase, and hyphenated filenames, and keeps imports predictable across Windows and case-sensitive environments. |\n\n## Services and state\n\n| Decision | Rule | Rationale |\n| --- | --- | --- |\n| Global singleton services own domain state and logic. | Each domain is a class in `src/services/**`, instantiated once at module level and exported, for example `export const indexesService = new IndexesService()`. React components do not own domain state. | Keeps business logic out of components, testable without a DOM, and shared across windows/views without Redux, Zustand, or Context stores. |\n| Service location follows usage scope. | If a service is specific to one UI element and used only there, place it beside that component. Generic or shared services, such as logging, database access, config, storage, or cross-screen domain logic, belong in `src/services/`. | Keeps component-owned behavior local while preserving `src/services/` for reusable application services. |\n| Consumers use direct imports or the service injector. | Direct import when no import cycle exists; use `src/services/service_injector.js` when a cycle would occur. Every global singleton service registers itself in its constructor with `inj.register('myService', this)`. | The service graph is dense; the injector is a bare global registry that defers resolution to call time. |\n| Services have a two-phase lifecycle. | Constructors only register and set unloaded state such as `null`. Config-dependent or service-dependent work runs in `init()`, `start()`, app bootstrap (`App.jsx`), or a `loaded` lifecycle event. `configService.config` is private; callers use `get`, `set`, and `clear`. | Module evaluation order is not guaranteed, so `configService` is not usable at import time. Reading config in a constructor is a bug. |\n\n\n## Events and React integration\n\n| Decision | Rule | Rationale |\n| --- | --- | --- |\n| Services notify observers through their own `EventTarget`. | Services expose an `EventTarget` and dispatch named `CustomEvent` domain events such as `activeIndex`, `added`, `deleted`, or `changedBox`. Observers subscribe with `addEventListener` and unsubscribe with `removeEventListener` on the owning service. | Decouples producers from consumers without depending on Node `EventEmitter`, which is not available in the browser-first React app. |\n| Custom hooks bridge service events to functional components. | Hooks in `src/components/hooks/`, such as `useActiveIndex` and `useProjectConfig`, seed `useState` from a service property, subscribe in `useEffect`, unsubscribe in cleanup, and return the value. Prefer hook + service over prop chains. | Components stay declarative and avoid direct event plumbing. |\n| Components subscribe at the smallest rendering boundary. | Root and layout components compose UI regions and pass structural inputs. Components that render changing application data subscribe through hooks themselves. Do not hoist changing data into ancestors only to pass it downward. | Limits rerenders to affected UI, protects transient state such as open popups, and avoids broad prop chains. |\n| Components use the app theme service path. | `App` owns theme mode through `useThemeMode()`, builds the MUI theme with `createAppTheme(mode)`, and provides it through `ThemeProvider`. Components read theme values with MUI APIs such as `useTheme`, `useMediaQuery`, and `sx`; only controls that change the palette mode receive `mode` and `onToggleTheme`. | Theme state, persistence, and palette construction stay centralized while components remain presentation-focused. |\n\r\n---\r\nid: F-061\r\ntitle: Select workTree from action popup\r\nstatus: ready\r\nowner: JB\r\naffects:\r\npolicy:\r\n  checkLinting: true\r\n  requireTests: true\r\ninternalId: 3f683f00-ed34-40a8-afeb-9932e62b4b34\r\n---\r\n\r\n## Goal\nUser can select the active worktree from the action popup. When the action popup is associated to a card, it reflects the worktree of that card (and also updates it). When the action popup is for the project agent, then the user can select the worktree on which to run the agent project wide.\n\n## Current state\n\n- The popup header contains the action selector, expand, and close controls in one row; it has no worktree control.\n- Card worktree assignments are stored in frontmatter and included in card action contexts. The project-agent context has no worktree assignment.\n- Electron uses a card's valid assignment only when an action has `needsWorkTree`. It rejects project contexts for such actions; actions without `needsWorkTree` run in the primary worktree.\n\n## implementation details\n\n- Add an accessible worktree icon/menu at the upper left, on the same row as the right-aligned expand and close buttons. Move the action selector to a second row.\n- List only valid linked worktrees reported by Git, plus an unassigned option. Keep invalid card assignments visible with their existing error.\n- In card context, initialize from the card assignment and persist changes through `updateCardWorktree`; keep the previous selection if saving fails.\n- Disable linked worktrees reserved by another active card. Background cards do not reserve worktrees.\n- Before persisting a card assignment, Electron creates a title-slug branch in the selected clean worktree from the opened project branch. Existing branches and dirty worktrees fail without changing the assignment.\n- In project context, keep the assignment in renderer service state for the current opened-project session only. Reset it when the project closes or changes; do not write it to project files, config, or schedules.\n- Project context can select any valid linked worktree, including one reserved by an active card, and does not prepare a branch.\n- Use the effective assignment for action filtering, prompt preparation, and execution. Electron resolves it only when `needsWorkTree` is true, accepting card or project context; missing, invalid, or unavailable assignments fail before process start. Actions without `needsWorkTree` still run in the primary worktree.\n- Disable assignment changes while an action is running. Report save and validation failures through `dialogService`.\n- Test card persistence/error handling, session reset, popup layout and accessibility, project/card execution resolution, missing/invalid assignments, and unchanged primary execution for actions without `needsWorkTree`.\n\n## acceptance criteria\n\n- Card popup shows and updates the card's worktree assignment.\n- Card popup disables worktrees reserved by another active card and prepares the selected worktree before saving.\n- Project-agent popup keeps one worktree assignment for the current opened-project session and does not persist it.\n- An action with `needsWorkTree` runs in the valid worktree supplied by its card or the project agent.\n- An action with `needsWorkTree` cannot start without a valid assignment and shows the reason.\n- An action without `needsWorkTree` runs in the primary worktree regardless of the displayed assignment.\n- Worktree control is accessible, occupies the top toolbar row, and cannot change during execution.\n\n## see also\n\r\n---\nid: F_62\ntitle: action entry points and popup\nstatus: ready\nowner: JB\naffects:\npolicy:\n  checkLinting: true\n  requireTests: true\ninternalId: d63ac574-4812-4643-8688-14399dad4099\n---\n\n## Goal\n\nShow context-sensitive action entry points based on `appliesTo` and open a resizable popup bound to an action `id` and context. The popup starts and cancels runs through the Electron runner from [[F-010c]] and links to related actions by id.\n\n## Current state\n\nThe existing popup receives resolved action objects and calls the React-side `ActionRunner`. Related actions are embedded resolved objects, and the popup has no Electron execution-id cancellation contract.\n\n## implementation details\n\n- Evaluate `appliesTo` for card, file, folder, and other supported contexts and display compact action entry points close to the matching item.\n- Always offer the built-in custom-prompt action in supported contexts.\n- Open the popup for the selected action `id` and context. Resolve current display data from the action service.\n- Make the popup resizable, with the resize handle placed according to popup position.\n- `Run` sends `{ actionId, context, runInput }` to the Electron runner.\n- While running, show `Cancel`; it sends the Electron execution id to the cancellation method and waits for the terminal event.\n- Show links for `onBefore` and `onAfter`; selecting one resolves that related action id and opens a popup with the same context.\n- Show phase-specific status/log output returned by Electron, including `okButNotAfter`.\n- Show `Schedule` as an entry point to [[F-022]] without duplicating schedule behavior here.\n- For a card with in-memory `currentAction`, disable every action entry point for that card until a terminal execution event clears it.\n\n## acceptance criteria\n\n- Entry points appear only for matching contexts, and a card with a current action disables all of them.\n- The custom-prompt action remains available in every supported context.\n- Activating an entry point opens a resizable popup bound to the action id and context.\n- `Run` sends no command, prompt template, or linked definitions from React.\n- `Cancel` stops a running Electron execution and the popup shows its cancelled result.\n- Related-action links continue to work after an action name changes.\n- Tests cover filtering, card disabling, popup open/resize, ID-based related navigation, run requests, cancellation, and terminal-state updates.\n\n## see also\n\n- `design\\architecture\\initial description\\action_popup.md`\n- `design\\architecture\\initial description\\writings\\running_actions.md`\n- `design\\feature_descriptions\\ready\\F_010a_action_model_and_loading.md`\n- `design\\feature_descriptions\\ready\\F_022_scheduled_actions.md`\n\r\n",
design\activity\card__3e151ae1-ffa3-42ba-819c-a6973683af03.json:64:          "content": "\u001b[2m2026-07-27T13:10:44.643497Z\u001b[0m \u001b[31mERROR\u001b[0m \u001b[2mcodex_core::tools::router\u001b[0m\u001b[2m:\u001b[0m \u001b[3merror\u001b[0m\u001b[2m=\u001b[0mExit code: 1\nWall time: 11.6 seconds\nOutput:\n19e0a6a Update design/feature_descriptions/B_75_position_edit_card_popup_mobile.md\n5fff680 Create design/feature_descriptions/B_75_position_edit_card_popup_mobile.md\n19e0a6a Update design/feature_descriptions/B_75_position_edit_card_popup_mobile.md\nimport { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\nimport {\n    DEFAULT_CARD_TYPES,\n    DEFAULT_ACTIONS_FOLDER,\n    DEFAULT_ARCHIVED_FOLDER,\n    DEFAULT_PROJECT_FOLDER,\n    DEFAULT_RELEASES_FOLDER,\n    DEFAULT_STATES,\n    defaultColumnAccent,\n} from '../data/data_types'\nimport { dataService } from '../services/data/data_service'\nimport { dialogService } from '../services/dialog_service'\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\nimport { openFilesService } from '../services/open_files_service'\nimport type { OpenDocument } from '../services/open_files_service'\nimport { telemetryService } from '../services/telemetry/telemetry_service'\nimport { workspaceViewService } from '../services/project/workspace_view_service'\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\nimport { CardView } from './card_view/card_view'\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\nimport { useProjectReference } from './hooks/use_project_reference'\nimport { TextView } from './text_view/text_view'\nimport { FileTreeView } from './text_view/file_tree_view'\nimport { useProjectConfig } from './hooks/use_project_config'\nimport { useWorkingFolder } from './hooks/use_working_folder'\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\nimport { MobileLayout } from './shell/mobile_layout'\nimport { MobileMainWindow } from './shell/mobile_main_window'\nimport { SplitLayout } from './shell/split_layout'\n\nconst WORKSPACE_PANEL_PADDING = 3\n\nfunction openDocumentPath(document: OpenDocument) {\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\n}\n\nfunction flushPendingCommits() {\n    flushMarkdownEditors()\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\n    })\n}\n\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\n    try {\n        flushMarkdownEditors()\n        await projectPersistenceService.flushPendingChanges()\n        lifecycleBridge.confirmFlush(requestId)\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\n    }\n}\n\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\n    try {\n        action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\ninterface ProjectWorkspaceProps {\n    auth: UseGithubAuthResult\n    isMenuOpen: boolean\n    onLeftPanelInteraction: () => void\n}\n\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\n    const theme = useTheme()\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\n    const project = useProjectReference()\n    const projectConfig = useProjectConfig()\n    const workingFolder = useWorkingFolder()\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\n    const states = projectConfig?.states ?? DEFAULT_STATES\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\n    const statusColors = useMemo(() => new Map(\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\n    ), [states])\n\n    useEffect(() => {\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\n    })\n\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\n        try {\n            await dataService.cards.createFolder(parentDirectory, name)\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder creation failed: ${name}` })\n            throw error\n        }\n    }, [])\n\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\n        try {\n            await dataService.cards.createMarkdownFile(parentDirectory, name)\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Markdown file creation failed: ${name}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFile = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFile(path)\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\n            if (document) openFilesService.closeDocument(document)\n            workspaceViewService.clearSelectedPath(path)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFolder = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFolder(path)\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\n            const documents = openFilesService.getSnapshot().documents\n            for (const document of documents) {\n                const openPath = openDocumentPath(document)\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\n            }\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    useEffect(() => {\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\n            flushMarkdownEditors()\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\n            // quit instead, so only prompt in a plain browser build.\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\n                event.preventDefault()\n                event.returnValue = ''\n            }\n\n            flushPendingCommits()\n        }\n\n        const handleVisibilityChange = () => {\n            if (document.visibilityState === 'hidden') flushPendingCommits()\n        }\n\n        const handleBlur = () => {\n            flushMarkdownEditors()\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\n        }\n\n        document.addEventListener('visibilitychange', handleVisibilityChange)\n        window.addEventListener('beforeunload', handleBeforeUnload)\n        window.addEventListener('blur', handleBlur)\n\n        return () => {\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\n            window.removeEventListener('beforeunload', handleBeforeUnload)\n            window.removeEventListener('blur', handleBlur)\n        }\n    }, [])\n\n    useEffect(() => {\n        const lifecycleBridge = getElectronLifecycleBridge()\n        if (!lifecycleBridge) return undefined\n\n        return lifecycleBridge.onFlushRequested((requestId) => {\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\n        })\n    }, [])\n\n    useEffect(() => {\n        const handleNavigationOpen = (event: Event) => {\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\n            // Reveal the card/file without changing the current view mode: highlight it in card view\n            // and open it in the service-owned text-view tabs.\n            workspaceViewService.selectPath(path)\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n            telemetryService.trackEvent('navigation')\n        }\n\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\n\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\n    }, [])\n\n    const fileTree = (\n        <Box\n            aria-label=\"File tree\"\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\n        >\n            <FileTreeView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                onCreateFolder={handleCreateFolder}\n                onCreateMarkdownFile={handleCreateMarkdownFile}\n                onDeleteFile={handleDeleteFile}\n                onDeleteFolder={handleDeleteFolder}\n                onLeftPanelInteraction={onLeftPanelInteraction}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                statusColors={statusColors}\n                workingFolder={workingFolder}\n            />\n        </Box>\n    )\n    const textView = (\n        <Paper\n            elevation={0}\n            sx={{\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: 2,\n                boxSizing: 'border-box',\n                display: 'flex',\n                height: '100%',\n                minHeight: 0,\n                overflow: 'hidden',\n                p: WORKSPACE_PANEL_PADDING,\n            }}\n        >\n            <TextView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                states={states}\n            />\n        </Paper>\n    )\n    const views = (\n        <>\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\n            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />\n        </>\n    )\n    const workspace = (\n        <ProjectWorkspaceAvailability>\n            {views}\n        </ProjectWorkspaceAvailability>\n    )\n    const navigation = project ? fileTree : (\n        <Box sx={{ p: 2 }}>\n            <Typography color=\"text.secondary\" variant=\"body2\">\n                No project navigation available.\n            </Typography>\n        </Box>\n    )\n\n    return (\n        <Box\n            aria-label=\"Project workspace\"\n            component=\"section\"\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            {isMobile ? (\n                <MobileMainWindow\n                    auth={auth}\n                    isMenuOpen={isMenuOpen}\n                    leftPanel={navigation}\n                    onCloseMenu={onLeftPanelInteraction}\n                    rightPanel={workspace}\n                    showNavigationInCards={!project}\n                />\n            ) : workspace}\n        </Box>\n    )\n}\n\r\nGet-Content : Cannot find path 'C:\\Users\\janbo\\Documents\\dev\\md2\\app\\src\\theme\\theme.ts' because it does not exist.\r\nAt line:2 char:304\r\n+ ... nts\\project_workspace.tsx'; Get-Content -Raw 'app\\src\\theme\\theme.ts'\r\n+                                 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\r\n    + CategoryInfo          : ObjectNotFound: (C:\\Users\\janbo\\...\\theme\\theme.ts:String) [Get-Content], ItemNotFoundEx \r\n   ception\r\n    + FullyQualifiedErrorId : PathNotFound,Microsoft.PowerShell.Commands.GetContentCommand\r\n \r\n\n",
design\activity\card__3e151ae1-ffa3-42ba-819c-a6973683af03.json:70:          "content": "19e0a6a Update design/feature_descriptions/B_75_position_edit_card_popup_mobile.md\n5fff680 Create design/feature_descriptions/B_75_position_edit_card_popup_mobile.md\n19e0a6a Update design/feature_descriptions/B_75_position_edit_card_popup_mobile.md\nimport { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'\nimport { useCallback, useEffect, useMemo, useRef } from 'react'\nimport type { UseGithubAuthResult } from '../auth/use_github_auth'\nimport {\n    DEFAULT_CARD_TYPES,\n    DEFAULT_ACTIONS_FOLDER,\n    DEFAULT_ARCHIVED_FOLDER,\n    DEFAULT_PROJECT_FOLDER,\n    DEFAULT_RELEASES_FOLDER,\n    DEFAULT_STATES,\n    defaultColumnAccent,\n} from '../data/data_types'\nimport { dataService } from '../services/data/data_service'\nimport { dialogService } from '../services/dialog_service'\nimport { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'\nimport { openFilesService } from '../services/open_files_service'\nimport type { OpenDocument } from '../services/open_files_service'\nimport { telemetryService } from '../services/telemetry/telemetry_service'\nimport { workspaceViewService } from '../services/project/workspace_view_service'\nimport { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'\nimport { projectPersistenceService } from '../services/project/project_persistence_service'\nimport { CardView } from './card_view/card_view'\nimport { flushMarkdownEditors } from './editor/markdown_editor_flush'\nimport { useProjectReference } from './hooks/use_project_reference'\nimport { TextView } from './text_view/text_view'\nimport { FileTreeView } from './text_view/file_tree_view'\nimport { useProjectConfig } from './hooks/use_project_config'\nimport { useWorkingFolder } from './hooks/use_working_folder'\nimport { ProjectWorkspaceAvailability } from './project_workspace_availability'\nimport { MobileLayout } from './shell/mobile_layout'\nimport { MobileMainWindow } from './shell/mobile_main_window'\nimport { SplitLayout } from './shell/split_layout'\n\nconst WORKSPACE_PANEL_PADDING = 3\n\nfunction openDocumentPath(document: OpenDocument) {\n    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath\n}\n\nfunction flushPendingCommits() {\n    flushMarkdownEditors()\n    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })\n    })\n}\n\nasync function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {\n    try {\n        flushMarkdownEditors()\n        await projectPersistenceService.flushPendingChanges()\n        lifecycleBridge.confirmFlush(requestId)\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })\n    }\n}\n\nfunction runWorkspaceEdit(action: () => void, fallbackMessage: string) {\n    try {\n        action()\n    } catch (error) {\n        dialogService.error(error, { fallbackMessage })\n    }\n}\n\ninterface ProjectWorkspaceProps {\n    auth: UseGithubAuthResult\n    isMenuOpen: boolean\n    onLeftPanelInteraction: () => void\n}\n\nexport function ProjectWorkspace(props: ProjectWorkspaceProps) {\n    const { auth, isMenuOpen, onLeftPanelInteraction } = props\n    const theme = useTheme()\n    const isMobile = useMediaQuery(theme.breakpoints.down('md'))\n    const project = useProjectReference()\n    const projectConfig = useProjectConfig()\n    const workingFolder = useWorkingFolder()\n    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES\n    const states = projectConfig?.states ?? DEFAULT_STATES\n    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER\n    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`\n    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`\n    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`\n    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)\n    const statusColors = useMemo(() => new Map(\n        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),\n    ), [states])\n\n    useEffect(() => {\n        onLeftPanelInteractionRef.current = onLeftPanelInteraction\n    })\n\n    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {\n        try {\n            await dataService.cards.createFolder(parentDirectory, name)\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder creation failed: ${name}` })\n            throw error\n        }\n    }, [])\n\n    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {\n        try {\n            await dataService.cards.createMarkdownFile(parentDirectory, name)\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Markdown file creation failed: ${name}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFile = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFile(path)\n            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)\n            if (document) openFilesService.closeDocument(document)\n            workspaceViewService.clearSelectedPath(path)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    const handleDeleteFolder = useCallback(async (path: string) => {\n        try {\n            await dataService.cards.deleteFolder(path)\n            const folderPrefix = `${path.replace(/\\/+$/u, '')}/`\n            const documents = openFilesService.getSnapshot().documents\n            for (const document of documents) {\n                const openPath = openDocumentPath(document)\n                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)\n            }\n            const selectedPath = workspaceViewService.getSnapshot().selectedPath\n            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)\n            onLeftPanelInteractionRef.current()\n        } catch (error) {\n            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })\n            throw error\n        }\n    }, [])\n\n    useEffect(() => {\n        const handleBeforeUnload = (event: BeforeUnloadEvent) => {\n            flushMarkdownEditors()\n            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()\n            // In Electron, vetoing beforeunload silently cancels the window close (no confirm\n            // dialog), leaving the app unclosable. The main process flushes pending commits on\n            // quit instead, so only prompt in a plain browser build.\n            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {\n                event.preventDefault()\n                event.returnValue = ''\n            }\n\n            flushPendingCommits()\n        }\n\n        const handleVisibilityChange = () => {\n            if (document.visibilityState === 'hidden') flushPendingCommits()\n        }\n\n        const handleBlur = () => {\n            flushMarkdownEditors()\n            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()\n        }\n\n        document.addEventListener('visibilitychange', handleVisibilityChange)\n        window.addEventListener('beforeunload', handleBeforeUnload)\n        window.addEventListener('blur', handleBlur)\n\n        return () => {\n            document.removeEventListener('visibilitychange', handleVisibilityChange)\n            window.removeEventListener('beforeunload', handleBeforeUnload)\n            window.removeEventListener('blur', handleBlur)\n        }\n    }, [])\n\n    useEffect(() => {\n        const lifecycleBridge = getElectronLifecycleBridge()\n        if (!lifecycleBridge) return undefined\n\n        return lifecycleBridge.onFlushRequested((requestId) => {\n            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)\n        })\n    }, [])\n\n    useEffect(() => {\n        const handleNavigationOpen = (event: Event) => {\n            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail\n            // Reveal the card/file without changing the current view mode: highlight it in card view\n            // and open it in the service-owned text-view tabs.\n            workspaceViewService.selectPath(path)\n            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)\n            telemetryService.trackEvent('navigation')\n        }\n\n        workspaceNavigationService.addEventListener('open', handleNavigationOpen)\n\n        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)\n    }, [])\n\n    const fileTree = (\n        <Box\n            aria-label=\"File tree\"\n            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}\n        >\n            <FileTreeView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                onCreateFolder={handleCreateFolder}\n                onCreateMarkdownFile={handleCreateMarkdownFile}\n                onDeleteFile={handleDeleteFile}\n                onDeleteFolder={handleDeleteFolder}\n                onLeftPanelInteraction={onLeftPanelInteraction}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                statusColors={statusColors}\n                workingFolder={workingFolder}\n            />\n        </Box>\n    )\n    const textView = (\n        <Paper\n            elevation={0}\n            sx={{\n                border: 1,\n                borderColor: 'divider',\n                borderRadius: 2,\n                boxSizing: 'border-box',\n                display: 'flex',\n                height: '100%',\n                minHeight: 0,\n                overflow: 'hidden',\n                p: WORKSPACE_PANEL_PADDING,\n            }}\n        >\n            <TextView\n                actionsFolder={actionsFolder}\n                archivedFolder={archivedFolder}\n                cardTypes={cardTypes}\n                projectFolder={projectFolder}\n                releasesFolder={releasesFolder}\n                states={states}\n            />\n        </Paper>\n    )\n    const views = (\n        <>\n            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}\n            <CardView cardTypes={cardTypes} isMobile={isMobile} states={states} />\n        </>\n    )\n    const workspace = (\n        <ProjectWorkspaceAvailability>\n            {views}\n        </ProjectWorkspaceAvailability>\n    )\n    const navigation = project ? fileTree : (\n        <Box sx={{ p: 2 }}>\n            <Typography color=\"text.secondary\" variant=\"body2\">\n                No project navigation available.\n            </Typography>\n        </Box>\n    )\n\n    return (\n        <Box\n            aria-label=\"Project workspace\"\n            component=\"section\"\n            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}\n        >\n            {isMobile ? (\n                <MobileMainWindow\n                    auth={auth}\n                    isMenuOpen={isMenuOpen}\n                    leftPanel={navigation}\n                    onCloseMenu={onLeftPanelInteraction}\n                    rightPanel={workspace}\n                    showNavigationInCards={!project}\n                />\n            ) : workspace}\n        </Box>\n    )\n}\n\r\nGet-Content : Cannot find path 'C:\\Users\\janbo\\Documents\\dev\\md2\\app\\src\\theme\\theme.ts' because it does not exist.\r\nAt line:2 char:304\r\n+ ... nts\\project_workspace.tsx'; Get-Content -Raw 'app\\src\\theme\\theme.ts'\r\n+                                 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\r\n    + CategoryInfo          : ObjectNotFound: (C:\\Users\\janbo\\...\\theme\\theme.ts:String) [Get-Content], ItemNotFoundEx \r\n   ception\r\n    + FullyQualifiedErrorId : PathNotFound,Microsoft.PowerShell.Commands.GetContentCommand\r\n \r\n",
design\activity\card__3e151ae1-ffa3-42ba-819c-a6973683af03.json:180:          "content": "design\\architecture\\current_data_model.md:19:| Card operations | `CardDeleteDialog`, `CardPolicyMenuItem`, `CardWorktreeIndicator` | Carry a `cardPath` to identify the card on which to operate. |\r\ndesign\\architecture\\class_relationships.md:158:        class CardDeleteDialog\ndesign\\architecture\\class_relationships.md:252:        class NewCardDialog\ndesign\\architecture\\class_relationships.md:433:    CardView --> AffectsEditorDialog\ndesign\\architecture\\class_relationships.md:441:    ProjectCardView --> CardDeleteDialog\ndesign\\architecture\\class_relationships.md:447:    CardBodyPopover --> CardDeleteDialog\ndesign\\architecture\\class_relationships.md:449:    CardBodyEditor --> CardPopupToolbarControls\ndesign\\architecture\\class_relationships.md:511:    AppMenu --> NewCardDialog\ndesign\\architecture\\class_relationships.md:521:    ProjectToolbarMenu --> NewCardDialog\ndesign\\architecture\\class_relationships.md:525:    NewCardDialog --> MarkdownEditor\ndesign\\architecture\\class_relationships.md:543:    NewCardDialog --> ProjectSessionService : creates card\ndesign\\feature_descriptions\\B_75_position_edit_card_popup_mobile.md:5:title: Position edit card popup mobile\ndesign\\feature_descriptions\\B_75_position_edit_card_popup_mobile.md:12:On mobile, the ´edit card´ popup should take up the window size.\ndesign\\releases\\0_0_2\\B_013_text_view_body_only.md:14:F-007 specifies \"full-file editing for text view and body editing for card view\". `TextView` feeds `activeCard.content` (header already stripped by the parsing service) into `MarkdownEditor` and saves through `updateCardBody` — the frontmatter header is invisible and uneditable in file mode. Header mistakes (wrong status, typo'd id) can't be fixed anywhere in the app.\ndesign\\releases\\0_0_2\\B_065_tab_open_blocks_on_editor_mount_and_spurious_flush_saves.md:27:`TextView` keys `MarkdownEditor` by `activeCard.path`, so every tab open *and every switch between already-open tabs* mounts a fresh MDXEditor synchronously in the click task. Measured in the running dev app (StrictMode):\ndesign\\releases\\0_0_2\\B_043_small_cleanups_2026_07.md:18:- **`window.confirm` for card deletion**: `ProjectCardView.deleteCard` (`app/src/components/card_view/project_card_view.tsx`) uses the native confirm while every other confirmation uses MUI dialogs; it is unstylable, blocks the renderer, and looks foreign in Electron. Replace with a small confirm `Dialog` (shared component if the release/branch dialogs don't already have one to reuse).\ndesign\\activity\\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:28:          \"content\": \"---\\r\\ninternalId: f2ec9e28-8064-4707-bce9-b62f24d57524\\r\\n---\\r\\n\\r\\n# App Style Guide â€” Kanban / MDÂ² (React + MUI)\\r\\n\\r\\nHow to build **any new component** so it matches the app. This is written for **Material UI v5+** components.\\r\\n\\r\\n**The theme is the source of truth.** All color, radius, base typography, and spacing units live in the single `createTheme` (defined in `GUIDANCE.md` Â§1/Â§9). This guide does **not** define colors â€” it tells you **which theme value to use for which role**, and covers the things the theme can't encode: layout, spacing/margins, borders, elevation, and component conventions.\\r\\n\\r\\n**The one rule that matters:** never write a raw hex, px radius, or magic color into a component. Read it from the theme (`theme.palette.*`, `theme.shape`, `theme.typography`, `theme.spacing`). If a component has a hardcoded hex in its `sx`/styled, it's wrong â€” that's exactly where the look drifts and where dark mode breaks.\\r\\n\\r\\n---\\r\\n\\r\\n## 1. How to consume the theme\\r\\n\\r\\n- **Colors:** `sx={{ color: 'text.secondary', bgcolor: 'background.paper', borderColor: 'divider' }}` â€” MUI resolves dotted palette paths automatically in `sx`. In `styled`/JS use the callback form: `styled(Box)(({ theme }) => ({ color: theme.palette.text.secondary }))`.\\r\\n- **Spacing:** use the 8px unit via the spacing scale â€” `sx={{ p: 2, gap: 1, mt: 1.5 }}` (`2` = 16px, `1` = 8px). Don't write `padding: '16px'`.\\r\\n- **Radius:** `borderRadius: 1` (= `theme.shape.borderRadius` = 8) and multiples; for the fixed non-8 radii see Â§4.\\r\\n- **Typography:** prefer `Typography variant=...` and `theme.typography.*` over ad-hoc `fontSize`.\\r\\n- **Custom tokens:** roles the default MUI palette doesn't cover (column/track surfaces, the strong/hover border steps, `text-3/4`, section-header color, `primary-bg` tint, status colors) must exist in the theme under a namespace (e.g. `theme.palette.custom.*`) with light + dark values. Consume them the same way â€” `bgcolor: 'custom.column'`. **Never inline their hex.** If a needed token doesn't exist yet, add it to the theme, don't hardcode it in the component.\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Role â†’ theme slot\\r\\n\\r\\nPick the slot by the element's **role**, not by how it looks in one mode:\\r\\n\\r\\n| Role | Theme slot |\\r\\n|---|---|\\r\\n| App background; tinted footer/action bars | `background.default` |\\r\\n| Column & sidebar surface | `custom.column` |\\r\\n| Segmented-control / toolbar track, hover fill | `custom.track` |\\r\\n| Card, dialog, popup, input surface | `background.paper` |\\r\\n| Hairlines, resting borders | `divider` |\\r\\n| Input borders, vertical separators | `custom.borderStrong` |\\r\\n| Border on hover | `custom.borderHover` |\\r\\n| Titles, values, headings | `text.primary` |\\r\\n| Body copy, field labels | `text.secondary` |\\r\\n| Meta, captions, resting icons | `custom.text3` |\\r\\n| Muted / placeholder / disabled | `custom.text4` |\\r\\n| Uppercase section/column headers | `custom.colHead` |\\r\\n| The one CTA, selection, focus, links, icon-hover | `primary.main` |\\r\\n| Contained-button hover | `primary.dark` |\\r\\n| Selected/tinted bg, focus ring, ID-chip bg | `custom.primaryBg` |\\r\\n| Text/icon on a primary fill | `primary.contrastText` |\\r\\n| Active / saved / online dot | `success.main` |\\r\\n| Destructive action | `error.main` |\\r\\n| Status swatch dots & ID-chip tints (decorative only) | `custom.status.*` |\\r\\n\\r\\nRules: **one** `primary` per surface (the CTA/selection accent) â€” everything else is `text-*`/`divider`. Status colors are **decoration only** (dots, chip tints), never interactive color. Dark-mode brightness/tinting is handled inside the theme's two palettes, so a correctly-sloted component needs zero per-mode code.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Layout\\r\\n\\r\\n- **Full-height app:** column flex â€” menu row / ribbon / content (`flex: 1; minHeight: 0`) / status bar. Fixed bands `flexShrink: 0`.\\r\\n- **Board:** horizontal-scroll flex row, `gap: 2` (16px), page padding `p: 2.5` (20px); columns `width: 296, flexShrink: 0`, internal column flex `gap: 1`.\\r\\n- **List view:** two-pane flex row filling the space between ribbon and status bar â€” sidebar `width: 280, flexShrink: 0`, editor pane `flex: 1, minWidth: 0` (the `minWidth: 0` is required so long content ellipsizes instead of blowing out the row).\\r\\n- **Panels (sidebar, editor card, dialogs):** column flex with stacked bands (header / [toolbar] / body / footer). The **body scrolls** (`overflow-y: auto; minHeight: 0`); header and footer are `flexShrink: 0` and never scroll away.\\r\\n- **Spacer pattern:** push trailing items with `<Box sx={{ flex: 1 }} />` rather than `margin-left: auto` sprinkled around, so rows stay predictable.\\r\\n- Use flex `gap` for spacing between siblings â€” don't hand-space with per-child margins.\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Spacing, margin & size conventions\\r\\n\\r\\n- **4/8px grid, via `theme.spacing`.** page padding `2.5`; between columns `2`; inside columns / between related controls `1`; dialog body gap `2â€“2.25`; field labelâ†’control gap `~0.9` (7px).\\r\\n- **Margins:** prefer padding on containers + flex `gap` over element margins. Where a floating panel needs breathing room (e.g. editor card, toolbar inside a panel), use container padding (`p: 2 / 2.5`), not margins on the children.\\r\\n- **Fixed heights (px):** menu row 44, ribbon 52, status bar 32, section header 40, tab row 40, standard button / control 34, dense icon button 26â€“28, input 42.\\r\\n- **Fixed widths (px):** column 296, sidebar 280, search 260, standard dialog 480, wide/editor dialog 760.\\r\\n- **Radius family (px):** buttons/icon-buttons 8 (small 6â€“7), inputs 9, cards 10, columns/panels 12, dialogs/popups 14, chips/pills 99, color swatches 3. `borderRadius: 1` covers the 8 case; use explicit `'9px'` etc. for the others.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Borders & elevation\\r\\n\\r\\n- **Rest = border, not shadow.** Resting surfaces: `border: '1px solid'`, `borderColor: 'divider'`. Inputs use `custom.borderStrong`. **Shadow only when floating or lifted** (hover, drag, dialogs/popovers).\\r\\n- **Separation between bands:** a single 1px `divider` hairline. Don't stack a heavy rule *and* an outline â€” one line, let background contrast do the rest. Vertical separators inside toolbars: a 20px-tall `custom.borderStrong` rule.\\r\\n- **Elevation ladder (only where floating):** card hover `0 4px 12px rgba(16,24,40,0.12)`; dragging MUI `elevation 8` + `rotate(2deg)`; contained button `0 1px 2px rgba(16,24,40,0.15)`; dialog/popup `0 24px 60px rgba(16,24,40,0.28)`; scrim `rgba(16,24,40,0.45)` + `backdropFilter: blur(2px)`.\\r\\n- Set `MuiPaper.elevation: 0` and `MuiButton.disableElevation` globally in the theme; add the shadows above explicitly where the ladder calls for it.\\r\\n- **On dark backgrounds shadows read as nothing** â€” the theme already handles this by making hover raise `borderColor` (`custom.borderHover`) instead of relying on shadow.\\r\\n\\r\\n---\\r\\n\\r\\n## 6. Typography usage\\r\\n\\r\\nDrive everything from theme variants / `theme.typography`; avoid ad-hoc `fontSize`.\\r\\n\\r\\n- Titles/values/headings â†’ `text.primary`; body & labels â†’ `text.secondary`; meta â†’ `custom.text3`.\\r\\n- **Field labels:** a plain `Typography` (12px/600, `text.secondary`) placed **above** the control â€” **never** MUI floating/outlined `TextField` labels (they clash with the app's flat-label style).\\r\\n- **Section/column headers:** `Typography variant=\\\"overline\\\"` (uppercase, `letterSpacing ~0.7px`, `fontWeight 700`, `custom.colHead`).\\r\\n- **ID chips only** use monospace; everything else is the theme's default family.\\r\\n- `button.textTransform: 'none'` and `button.fontWeight: 600` are set in the theme â€” don't re-uppercase buttons.\\r\\n\\r\\n---\\r\\n\\r\\n## 7. Interaction states\\r\\n\\r\\nConsistent across all components; all colors from the theme:\\r\\n\\r\\n- **Ghost icon button** (`IconButton`): transparent â†’ hover `bgcolor: track` (or `background.paper` on a colored panel) + `color: primary.main`. Override MUI's default circular hover tint via `sx`.\\r\\n- **Outlined button:** `divider` border, `text.secondary` â†’ hover `borderColor/color: primary.main`. Destructive: hover `borderColor: error.main` + `bgcolor: custom.dangerBg`.\\r\\n- **Contained (primary) CTA:** `primary.main` + small shadow â†’ hover `primary.dark`.\\r\\n- **Input/field focus:** `borderColor: primary.main` + `boxShadow: 0 0 0 3px` in `custom.primaryBg` (the soft halo). Unfocused hover: `borderColor: custom.borderHover`.\\r\\n- **List/tree row:** hover `bgcolor: track`; selected `bgcolor: custom.primaryBg` + title `text.primary`.\\r\\n- **Row-level actions** (delete, â‹®): hidden at rest, shown on `:hover`/`:focus-within` via **opacity** (keep in DOM so width doesn't jump).\\r\\n- **Active tab/menu item:** 2px `primary.main` bottom border + `primary.main` text.\\r\\n- Every icon-only control gets a `Tooltip` (theme sets `arrow: true`) **and** an `aria-label`.\\r\\n\\r\\n---\\r\\n\\r\\n## 8. Component conventions (MUI primitives)\\r\\n\\r\\n- **Buttons:** `Button variant=\\\"contained\\\"` = the single CTA per surface; `variant=\\\"outlined\\\"` = secondary; `variant=\\\"text\\\"` = tertiary. Icon-only â†’ `IconButton` in a `Tooltip`. Don't use `Link` or text `Button` where an action button belongs (that reproduces the old text-link look).\\r\\n- **Icons:** `@mui/icons-material` **Outlined** variants; `fontSize: 18` in 34px buttons, `16` in dense, `13â€“15` inline. Don't hand-draw SVG.\\r\\n- **ID chip:** monospace, accent text on `custom.primaryBg`/status tint, `radius 5, flexShrink: 0`.\\r\\n- **Count chip:** `background.paper` bg, 1px `divider`, radius 9â€“10, `custom.text3`.\\r\\n- **State dot:** 7â€“8px circle + `text-3` label; green (`success.main`) = active/saved/online.\\r\\n- **Search:** pill `TextField` (`borderRadius: 99`, `bgcolor: background.default`), search start-adornment, `âŒ˜K` keycap end-adornment.\\r\\n- **Select:** `size=\\\"small\\\"`, optional dot+name via `renderValue`; 42px / radius-9 frame. When a select has a tooltip, keep the tooltip available while the select is closed and explicitly hide it for the entire time the select menu is open so it cannot cover the first option.\\r\\n- **Segmented control** (view switch, formatting toolbar): `ToggleButtonGroup` on a `custom.track` background; selected segment `background.paper` + `0 1px 2px` shadow + `primary` text.\\r\\n- **Dialog / popup:** `Dialog`/`Popover` with `PaperProps` â†’ `background.paper`, 1px `divider`, radius 14, big shadow; scrim via `slotProps.backdrop` (blur + tint). Bands separated by hairlines; footer on a `background.default` bar with top hairline; actions right-aligned (outlined Cancel + contained CTA). `autoFocus` first field; submit on `Enter` (`âŒ˜/Ctrl+Enter` in a textarea); close on `Esc`/backdrop.\\r\\n- **Empty state:** dashed target â€” `1.5px dashed custom.borderStrong`, radius 10, centered icon + `custom.text4` label. No \\\"click to add\\\" placeholder blocks.\\r\\n\\r\\n---\\r\\n\\r\\n## 9. Definition of done for a new component\\r\\n\\r\\n1. Zero hardcoded hex / raw px colors â€” every value comes from `theme.palette` / `theme.shape` / `theme.spacing` / `theme.typography`.\\r\\n2. Correct roleâ†’slot mapping (Â§2); at most one `primary` CTA on the surface.\\r\\n3. Borders at rest, shadow only when floating (Â§5); bands split by a single hairline.\\r\\n4. Hover **and** focus states on every interactive element (Â§7); icon buttons have tooltip + `aria-label`.\\r\\n5. Body scrolls, header/footer pinned; `minWidth: 0` on flex children that hold long text.\\r\\n6. Toggle to dark mode and confirm nothing breaks â€” if it does, you hardcoded a color somewhere (Â§1).\\r\\n\\r\\nComponent-specific detail lives in `GUIDANCE.md` (theme definition + board/list/dialog), `CARD_POPUP_GUIDE.md`, `RUN_DIALOG_GUIDE.md`, and `SIDEBAR_ACTIONS_GUIDE.md`.\\r\\n\",\ndesign\\activity\\card__e08c4b32-0bff-42a8-9df2-b0df009606ab.json:46:          \"content\": \"design\\\\feature_descriptions\\\\B_002_github_push_semantics.md:26:- If the fallback UI-honesty option is chosen instead: GitHub mode shows no manual-push option and the docs/config reflect that.\\ndesktop\\\\vitest.config.mjs:1:import { defineConfig } from 'vitest/config';\\ndesktop\\\\vitest.config.mjs:3:export default defineConfig({});\\ndesktop\\\\electron-builder.config.cjs:1:const { createBuilderConfig } = require('./packaging/builder_config')\\ndesktop\\\\electron-builder.config.cjs:3:module.exports = createBuilderConfig()\\ndesktop\\\\main.js:1:const { app, BrowserWindow, Menu, dialog, ipcMain, nativeTheme, shell } = require('electron');\\ndesktop\\\\main.js:11:const { readDesktopConfig, resolveBridgeAllowedOrigins, writeDesktopConfig } = require('./src/shell/config');\\ndesktop\\\\main.js:67:    agentConfigProvider: () => readDesktopConfig(store),\\ndesktop\\\\main.js:82:    desktopConfigStore: store,\\ndesktop\\\\main.js:87:    readDesktopConfig,\\ndesktop\\\\main.js:98:    const result = await dialog.showOpenDialog(window, {\\ndesktop\\\\main.js:109:    const 