export const CARD_RUN_POPUP_SIZE_STORAGE_KEY = 'md2.cardRunPopupSize'
export const PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY = 'md2.projectAgentPopupSize'

interface ActionPopupContentProps {
    activeActionStatuses: Record<string, ActionExecutionStatus>
    action: ActionDefinition
    actions: ActionDefinition[]
    anchorElement: HTMLElement | null
    assignmentContext: ActionContext
    baseContext: ActionContext
    draggable?: boolean
    fullHeight: boolean
    onAddAction: () => void
    onClose: () => void
    onConversationViewed?: (conversation: AgentConversation) => void
    onSelectAction: (actionId: string) => void
    onToggleFullHeight: () => void
    open: boolean
    primaryPath: string | null
    showSaveControls: boolean
    titleId: string
    unseenResultActionIds?: string[]
}

/**
 * The message is rebuilt on every render but only reads the worktree list on the failing
 * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.
 */
function worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {
    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError
    if (!hasWorktreeAssignment && !action.needsWorkTree) return null
    if (context.kind !== 'card' && context.kind !== 'project') {
        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for worktree execution'
        return `Action "${action.label}" requires card or project context ${reason}`
    }
    if (context.worktreeError) return context.worktreeError
    if (context.worktree === undefined) return `Action "${action.label}" requires a worktree assignment`
    if (!/^[1-9]\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`

    const worktree = Number.parseInt(context.worktree, 10)
    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`
    const record = worktreeService.getRecords()[worktree - 1]
    if (!record) return `Configured worktree ${worktree} does not exist`
    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`

    return null
}

function worktreeAssignmentTarget(context: ActionContext): WorktreeAssignmentTarget | null {
    if (context.kind === 'project') return { kind: 'project' }
    if ((context.kind === 'card' || context.kind === 'file') && context.file) return { kind: 'card', path: context.file }

    return null
}

/** Presentation and execution behavior for the internally selected popup action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const {
        action, actions, activeActionStatuses, anchorElement, assignmentContext, baseContext, draggable, fullHeight, onAddAction, onClose,
        onSelectAction, onToggleFullHeight, open, primaryPath, showSaveControls, titleId, unseenResultActionIds = [],
    } = props
    const controller = useActionPopupController({
        action,
        context: assignmentContext,
        scheduleContext: baseContext,
        enableConversations: action.type === 'agent',
        executionValidationError: worktreeValidationMessage(action, assignmentContext),
    })
    const sessionActive = controller.runStatus === 'queued'
        || controller.runStatus === 'running'
        || controller.runStatus === 'waitingForInput'
    const showAgentInteraction = action.type === 'agent' || controller.agentActive
    const sizeStorageKey = baseContext.kind === 'project'
        ? PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY
        : CARD_RUN_POPUP_SIZE_STORAGE_KEY
    const promptDraft = useMemo(
        () => new ActionPromptDraft(controller.prompt, controller.promptResetToken),
        [controller.prompt, controller.promptResetToken],
    )
    const parsedWorktree = assignmentContext.worktree && /^[1-9]\d*$/u.test(assignmentContext.worktree)
        ? Number.parseInt(assignmentContext.worktree, 10)
        : null
    const worktreeAssignment: WorktreeAssignment = {
        worktree: parsedWorktree,
        worktreeError: assignmentContext.worktreeError ?? null,
        worktreeValue: assignmentContext.worktree ?? null,
    }
    const assignmentTarget = baseContext.kind === 'card' || baseContext.kind === 'file' || baseContext.kind === 'project'
        ? worktreeAssignmentTarget(baseContext)
        : null
    const handleRunShortcut = () => {
        const prompt = promptDraft.getSnapshot()
        if (actionPopupRunDisabled(action, controller, prompt, showSaveControls)) return
        if (showSaveControls) void controller.handleSaveAndRun(prompt)
        else void controller.handleRun(prompt)
    }

    return (
        <ResizablePopper
            anchorElement={anchorElement}
            draggable={draggable}
            fullHeight={fullHeight}
            initialSize={{ height: 450, width: 400 }}
            labelId={titleId}
            onClose={onClose}
            open={open}
            paperSx={{
                bgcolor: 'background.paper',
                border: 1,
                borderColor: 'divider',
                borderRadius: '14px',
                boxShadow: '0 24px 60px rgba(16,24,40,0.28)',
                flexDirection: 'column',
            }}
            resizeFromAllSides
            resizeLabel="Resize action popup"
            storageKey={sizeStorageKey}
        >
            <Typography
                id={titleId}
                sx={{ clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', height: 1, overflow: 'hidden', position: 'absolute', whiteSpace: 'nowrap', width: 1 }}
            >
                Run actions
            </Typography>
            <Box
                data-drag-handle={draggable ? 'true' : undefined}
                sx={{
                    borderBottom: 1, borderColor: 'divider', cursor: draggable ? 'move' : undefined,
                    display: 'flex', flexDirection: 'column', gap: 1, px: 1.5, py: 1.5,
                }}
            >
                <Box data-testid="action-popup-toolbar" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                    {assignmentTarget ? (
                        <WorktreeSelector
                            assignment={worktreeAssignment}
                            assignmentTarget={assignmentTarget}
                            disabled={sessionActive}
                            primaryPath={primaryPath}
                        />
                    ) : null}
                    {action.type === 'agent' ? (
                        <ActionConversationPicker
                            conversations={controller.conversations}
                            disabled={sessionActive}
                            loading={controller.conversationHistoryLoading}
                            onChange={controller.handleConversationChange}
                            selectedPath={controller.displayedConversation?.path ?? ''}
                        />
                    ) : null}
                    <Box sx={{ flex: 1 }} />
                    <Tooltip title={fullHeight ? 'Collapse downward' : 'Expand upward'}>
                        <IconButton
                            aria-label={fullHeight ? 'Collapse downward' : 'Expand upward'}
                            onClick={onToggleFullHeight}
                            size="small"
                            sx={{ flexShrink: 0, height: 30, width: 30 }}
                        >
                            {fullHeight ? <ArrowCollapseVertical sx={{ fontSize: 18 }} /> : <ArrowExpandVertical sx={{ fontSize: 18 }} />}
                        </IconButton>
                    </Tooltip>
                    <IconButton aria-label="Close" onClick={onClose} size="small" sx={{ flexShrink: 0, height: 30, width: 30 }}>
                        <Close sx={{ fontSize: 18 }} />
                    </IconButton>
                </Box>
                <ActionSelector
                    activeActionStatuses={activeActionStatuses}
                    adding={showSaveControls}
                    actions={actions}
                    onAdd={onAddAction}
                    onSelect={onSelectAction}
                    selectedAction={action}
                    unseenResultActionIds={unseenResultActionIds}
                />
            </Box>
            <Stack spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                {showAgentInteraction ? (
                    <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                        {showSaveControls ? (
                            <ActionAgentPresetName
                                actionLabel={controller.actionLabel}
                                onActionLabelChange={controller.handleActionLabelChange}
                                onRunShortcut={handleRunShortcut}
                            />
                        ) : null}
                        <Box sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', flexWrap: 'wrap', fontSize: 12, gap: 0.75 }}>
                            {action.type === 'agent' ? (
                                <ActionAgentSelectors
                                    agent={controller.agent}
                                    agentAvailability={controller.agentAvailability}
                                    agentProfiles={controller.agentProfiles}
                                    disabled={sessionActive}
                                    model={controller.model}
                                    onAgentChange={controller.handleAgentChange}
                                    onModelChange={controller.handleModelChange}
                                    onThinkingLevelChange={controller.handleThinkingLevelChange}
                                    selectedAgentModels={controller.selectedAgentModels}
                                    thinkingLevel={controller.thinkingLevel}
                                />
                            ) : null}
                            <ActionLogErrorDisplay logs={controller.runLogs} />
                        </Box>
                        <ActionConversationChat
                            conversation={controller.displayedConversation}
                            onConversationViewed={props.onConversationViewed}
                            status={controller.runStatus}
                        />
                        <ActionAgentPrompt
                            convertMessage={controller.convertMessage}
                            disabled={false}
                            onPromptChange={controller.handlePromptChange}
                            onRunShortcut={handleRunShortcut}
                            promptDraft={promptDraft}
                            promptFailed={controller.promptPreparationFailed}
                            promptLoading={controller.promptPreparationPending}
                        />
                        {controller.structuredQuestion ? (
                            <ActionAgentQuestion
                                onAnswer={controller.handleAnswerQuestion}
                                questions={controller.structuredQuestion.questions}
                            />
                        ) : null}
                    </Stack>
                ) : null}
                {controller.isFollowUp && action.phrases.length > 0 ? (
                    <ActionPhraseButtons
                        onDoubleClick={controller.handlePhraseDoubleClick}
                        onSelect={controller.handlePhraseSelect}
                        phrases={action.phrases}
                    />
                ) : null}
                {controller.scheduleOpen ? (
                    <ActionScheduleForm
                        message={controller.scheduleMessage}
                        onRegister={controller.handleScheduleAction}
                        onTimestampChange={controller.handleScheduleTimestampChange}
                        timestamp={controller.scheduleTimestamp}
                    />
                ) : null}
                {action.type !== 'agent' && controller.runStatus !== 'idle' ? (
                    <ActionRunStatus
                        color={statusColor(controller.runStatus)}
                        logs={controller.runLogs}
                        status={controller.runStatus}
                    />
                ) : null}
                {controller.executionDisabledMessage ? (
                    <Typography color="text.secondary" role="note" variant="caption">
                        {controller.executionDisabledMessage}
                    </Typography>
                ) : null}
                {controller.executionValidationError ? (
                    <Typography color="error.main" role="alert" variant="caption">
                        {controller.executionValidationError}
                    </Typography>
                ) : null}
                {action.type !== 'agent' ? (
                    <ActionRunHistory compact entries={controller.history} error={controller.historyError} />
                ) : null}
            </Stack>
            <ActionPopupBottomRow
                action={action}
                assignmentContext={assignmentContext}
                baseContext={baseContext}
                controller={controller}
                promptDraft={promptDraft}
                showSaveControls={showSaveControls}
            />
        </ResizablePopper>
    )
}

import type { ActionContext } from '../../data/action_context'
import type { ActionScheduleTrigger } from '../../data/action_schedule_types'
import type { ActionDefinition } from '../../data/action_types'
import type { ActionRunInput, ActionRunResult } from '../../data/action_run_types'
import type { AgentConversation } from '../../data/data_types'
import { getElectronActionBridge, type ActionRunHistoryEntry } from '../../data/electron_action_bridge'
import { defaultActionHistoryLoader, loadActionHistory } from '../../services/actions/action_history'
import { actionFilePath, createActionDefinition, type ConvertPromptToActionInput } from '../../services/actions/action_definition_writer'
import { dataService } from '../../services/data/data_service'
import { projectPersistenceService } from '../../services/project/project_persistence_service'
import { cancelElectronAction, runElectronAction } from '../../services/actions/electron_action_runner'
import {
    answerActionQuestion,
    finishActionExecution,
    sendActionMessage,
} from '../../services/actions/action_execution_service'
import { flushMarkdownEditors } from '../editor/markdown_editor_flush'

export type PopupRunStatus = 'idle' | 'queued' | 'running' | 'waitingForInput' | ActionRunResult['status']
export type CancelAction = (executionId: string) => Promise<void>
export type SendMessage = (executionId: string, content: string) => Promise<void>
export type FinishAction = (executionId: string) => Promise<void>
export type AnswerQuestion = (
    executionId: string,
    requestId: number | string | null,
    answers: Record<string, string[]>,
) => Promise<void>
export type ConvertPromptToAction = (input: ConvertPromptToActionInput) => Promise<{ path: string }>
export type LoadHistory = (action: ActionDefinition, context: ActionContext) => Promise<ActionRunHistoryEntry[]>
export type LoadConversation = (path: string) => Promise<AgentConversation>
export type LoadConversations = (context: ActionContext) => Promise<AgentConversation[]>
export type PreparePrompt = (action: ActionDefinition, context: ActionContext) => Promise<string>
export type RunAction = (
    action: ActionDefinition,
    context: ActionContext,
    input?: ActionRunInput,
    onStarted?: (executionId: string) => void,
) => Promise<ActionRunResult>
export type ScheduleAction = (action: ActionDefinition, context: ActionContext, trigger: ActionScheduleTrigger) => Promise<void>

export function defaultRunAction(
    action: ActionDefinition,
    context: ActionContext,
    input?: ActionRunInput,
    onStarted?: (executionId: string) => void,
) {
    return runElectronAction(action, context, input, onStarted)
}

export function defaultLoadHistory(action: ActionDefinition, context: ActionContext) {
    return loadActionHistory({
        action,
        actionHistoryLoader: defaultActionHistoryLoader,
        bridge: getElectronActionBridge(),
        context,
    })
}

export function defaultLoadConversation(path: string) {
    return dataService.loadAgentConversation(path)
}

export function defaultLoadConversations(context: ActionContext) {
    return dataService.listAgentConversations(context)
}

export async function defaultPreparePrompt(action: ActionDefinition, context: ActionContext) {
    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Preparing action prompts requires the Electron desktop app')
    flushMarkdownEditors()
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()
    const result = await bridge.prepareActionPrompt({ actionId: action.id, context })

    return result.prompt
}

export async function defaultConvertPromptToAction(input: ConvertPromptToActionInput) {
    const actionsFolder = dataService.getConfig()?.actionsFolder
    if (!actionsFolder) throw new Error('Cannot convert prompt before project config is loaded')

    const definition = createActionDefinition(input)
    const path = actionFilePath(actionsFolder, definition.label)
    await dataService.cards.saveProjectFile({ content: `${JSON.stringify(definition, null, 2)}\n`, path }, `Create ${path}`)

    return { definition, path }
}

export function defaultCancelAction(executionId: string) {
    return cancelElectronAction(executionId)
}

export function defaultSendMessage(executionId: string, content: string) {
    return sendActionMessage(executionId, content)
}

export function defaultFinishAction(executionId: string) {
    return finishActionExecution(executionId)
}

export function defaultAnswerQuestion(
    executionId: string,
    requestId: number | string | null,
    answers: Record<string, string[]>,
) {
    return answerActionQuestion(executionId, requestId, answers)
}

export async function defaultScheduleAction(action: ActionDefinition, context: ActionContext, trigger: ActionScheduleTrigger) {
    const bridge = getElectronActionBridge()
    if (!bridge?.registerActionSchedule) throw new Error('Scheduling actions requires Electron local mode')

    await bridge.registerActionSchedule({ actionId: action.id, context, trigger })
}

export function statusColor(status: PopupRunStatus) {
    if (status === 'completed') return 'success.main'
    if (status === 'failed') return 'error.main'
    if (status === 'queued' || status === 'running' || status === 'waitingForInput') return 'info.main'
    if (status === 'okButNotAfter' || status === 'cancelled') return 'warning.main'

    return 'text.secondary'
}

import { Box, Typography } from '@mui/material'
import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from 'react'
import { MarkdownEditor, type MarkdownEditorHandle } from '../editor/markdown_editor'
import type { ActionPromptDraft } from './action_prompt_draft'

const MIN_PROMPT_HEIGHT = 72
const MIN_CHAT_HEIGHT = 96
const DEFAULT_PROMPT_HEIGHT = 140
const PROMPT_RESIZE_STEP = 24
const PROMPT_HEIGHT_STORAGE_KEY = 'md2.actionPromptHeight'

function readStoredPromptHeight(): number {
    const storedValue = window.localStorage.getItem(PROMPT_HEIGHT_STORAGE_KEY)
    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN

    return Number.isNaN(parsedValue) ? DEFAULT_PROMPT_HEIGHT : parsedValue
}

interface ActionAgentPromptProps {
    convertMessage: string | null
    disabled: boolean
    onPromptChange: (value: string) => void
    onRunShortcut?: () => void
    promptDraft: ActionPromptDraft
    promptFailed: boolean
    promptLoading: boolean
}

/** Resizable prompt editor shown below an agent conversation. */
export function ActionAgentPrompt(props: ActionAgentPromptProps) {
    const {convertMessage, disabled, onPromptChange, onRunShortcut, promptDraft, promptFailed, promptLoading} = props
    const promptEditorRef = useRef<MarkdownEditorHandle>(null)
    const promptHeightStartRef = useRef(0)
    const pointerStartYRef = useRef(0)
    const splitContainerRef = useRef<HTMLElement | null>(null)
    const [promptHeight, setPromptHeight] = useState(readStoredPromptHeight)
    const [resizingPrompt, setResizingPrompt] = useState(false)

    useEffect(() => {
        promptEditorRef.current?.setMarkdown(promptDraft.getSnapshot())
    }, [promptDraft])

    const clampPromptHeight = (proposed: number) => {
        const container = splitContainerRef.current
        const available = container ? container.getBoundingClientRect().height - MIN_CHAT_HEIGHT : proposed
        const max = Math.max(MIN_PROMPT_HEIGHT, available)

        return Math.min(Math.max(proposed, MIN_PROMPT_HEIGHT), max)
    }

    const persistPromptHeight = (height: number) => {
        window.localStorage.setItem(PROMPT_HEIGHT_STORAGE_KEY, String(Math.round(height)))
    }

    const handleSplitPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
        event.preventDefault()
        splitContainerRef.current = event.currentTarget.parentElement
        promptHeightStartRef.current = promptHeight
        pointerStartYRef.current = event.clientY
        setResizingPrompt(true)
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }

    const handleSplitPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (!resizingPrompt) return

        const delta = pointerStartYRef.current - event.clientY
        setPromptHeight(clampPromptHeight(promptHeightStartRef.current + delta))
    }

    const handleSplitPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (!resizingPrompt) return

        setResizingPrompt(false)
        event.currentTarget.releasePointerCapture?.(event.pointerId)
        setPromptHeight((height) => {
            persistPromptHeight(height)

            return height
        })
    }

    const handleSplitKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        splitContainerRef.current = event.currentTarget.parentElement
        const nextByKey: Record<string, number> = {
            ArrowDown: promptHeight - PROMPT_RESIZE_STEP,
            ArrowUp: promptHeight + PROMPT_RESIZE_STEP,
        }
        const next = nextByKey[event.key]
        if (next === undefined) return

        event.preventDefault()
        const clamped = clampPromptHeight(next)
        setPromptHeight(clamped)
        persistPromptHeight(clamped)
    }

    const handlePromptKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key !== 'Enter' || (!event.ctrlKey && !event.metaKey) || !onRunShortcut) return

        event.preventDefault()
        promptEditorRef.current?.flush()
        onRunShortcut()
    }

    return (
        <>
            <Box
                aria-label="Resize prompt"
                aria-orientation="horizontal"
                aria-valuemin={MIN_PROMPT_HEIGHT}
                aria-valuenow={Math.round(promptHeight)}
                onKeyDown={handleSplitKeyDown}
                onPointerDown={handleSplitPointerDown}
                onPointerMove={handleSplitPointerMove}
                onPointerUp={handleSplitPointerUp}
                role="separator"
                sx={{
                    bgcolor: resizingPrompt ? 'primary.main' : 'divider',
                    borderRadius: '2px',
                    cursor: 'row-resize',
                    flexShrink: 0,
                    height: '3px',
                    mx: 'auto',
                    my: '2px',
                    width: '100%',
                    '&:hover': { bgcolor: 'primary.main' },
                }}
                tabIndex={0}
            />
            <Box
                aria-label="Prompt"
                onKeyDown={handlePromptKeyDown}
                sx={{
                    borderRadius: '9px',
                    border: 1,
                    borderColor: (theme) => theme.palette.mode === 'dark' ? '#364152' : '#d5dbe3',
                    flexShrink: 0,
                    height: promptHeight,
                    overflowY: 'auto',
                    px: 1,
                    '&:focus-within': {
                        borderColor: 'primary.main',
                        boxShadow: (theme) => `0 0 0 3px ${theme.palette.action.selected}`,
                    },
                }}
            >
                <MarkdownEditor
                    flushOnBlur
                    hideToolbar
                    markdown={promptDraft.getSnapshot()}
                    onChange={onPromptChange}
                    onLiveChange={promptDraft.set}
                    readOnly={disabled || promptLoading || promptFailed}
                    ref={promptEditorRef}
                />
            </Box>
            {convertMessage ? (
                <Typography color="text.secondary" role="status" variant="caption">
                    {convertMessage}
                </Typography>
            ) : null}
        </>
    )
}

