import { Box, Button, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../data/action_context'
import type { ProjectCard } from '../../data/data_types'
import { cardActionPopupService } from '../../services/actions/card_action_popup_service'
import { hasUnseenAgentResult } from '../../services/agents/agent_acknowledgement_service'
import { agentStateDescription, cardAgentState } from '../../services/agents/card_agent_state'
import { useRunningActionForContext } from '../hooks/use_action_executions'

interface CardRunButtonProps {
    card: ProjectCard
    context: ActionContext
    projectKey: string
}

/** Opens the card action selector and execution popup, and surfaces the card's agent state. */
export function CardRunButton({ card, context, projectKey }: CardRunButtonProps) {
    const agentState = cardAgentState(projectKey, card)
    const runningExecution = useRunningActionForContext(context)
    const liveStatus = runningExecution?.status
    const isQueued = liveStatus === 'queued'
    const isWaiting = liveStatus ? liveStatus === 'waitingForInput' : agentState === 'waiting for input'
    const isRunning = liveStatus ? liveStatus === 'running' : agentState === 'running'
    const isUnseen = !isQueued && !isWaiting && !isRunning && agentState === 'unseen result'
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? agentStateDescription('waiting for input')
            : isRunning && agentState !== 'running'
                ? 'Action is running'
                : agentStateDescription(agentState)
    const accent = isWaiting ? 'warning.main' : isUnseen ? 'info.main' : 'primary.main'
    const unseenResultActionIds = [...new Set(card.agentConversations.flatMap((conversation) => {
        if (!conversation.actionId || !hasUnseenAgentResult(projectKey, card.path, [conversation])) return []

        return [conversation.actionId]
    }))]

    const handleRun = (event: MouseEvent<HTMLButtonElement>) => {
        cardActionPopupService.toggle(context, event.currentTarget, projectKey, unseenResultActionIds)
    }

    const button = (
        <Box
            sx={(theme) => ({
                borderRadius: 99,
                display: 'inline-flex',
                overflow: 'hidden',
                p: isRunning ? '1.5px' : 0,
                position: 'relative',
                ...(isRunning && {
                    '@keyframes md2-run-spin': { to: { transform: 'rotate(1turn)' } },
                    '&::before': {
                        animation: 'md2-run-spin 1s linear infinite',
                        background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                        content: '""',
                        inset: '-50%',
                        pointerEvents: 'none',
                        position: 'absolute',
                    },
                }),
            })}
        >
            <Button
                aria-label={stateDescription ? `Run â€” ${stateDescription}` : 'Run'}
                onClick={handleRun}
                size="small"
                startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                sx={{
                    bgcolor: 'background.paper',
                    borderColor: isRunning ? 'transparent' : isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    borderRadius: 99,
                    color: isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    fontSize: 11.5,
                    height: 26,
                    minWidth: 0,
                    position: 'relative',
                    px: 1.25,
                    zIndex: 1,
                    '&:hover': { bgcolor: 'background.paper' },
                }}
                variant="outlined"
            >
                Run
            </Button>
            {isWaiting ? <HelpCircleOutline sx={{ color: accent, fontSize: 11, position: 'absolute', right: -2, top: -2, zIndex: 2 }} /> : null}
            {isUnseen ? <Circle sx={{ color: accent, fontSize: 8, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
        </Box>
    )

    return (
        <Tooltip title={stateDescription ?? ''}>{button}</Tooltip>
    )
}

import type { AgentConversation } from '../../data/data_types'
import { dialogService } from '../../services/dialog_service'
import { agentAcknowledgementService } from '../../services/agents/agent_acknowledgement_service'
import {
    cardActionPopupService,
    type CardActionPopupEntry,
} from '../../services/actions/card_action_popup_service'
import { ActionPopup } from './action_popup'

interface CardActionPopupHostEntryProps {
    entry: CardActionPopupEntry
}

/** Renders one service-owned card action popup with isolated local controller state. */
export function CardActionPopupHostEntry({ entry }: CardActionPopupHostEntryProps) {
    const handleClose = () => {
        cardActionPopupService.close(entry.id)
    }

    const handleConversationViewed = (conversation: AgentConversation) => {
        try {
            const cardPath = entry.context.file
            if (!cardPath) throw new Error('Cannot acknowledge a card conversation without a card path')

            agentAcknowledgementService.acknowledge(entry.projectKey, cardPath, [conversation])
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card conversation could not be acknowledged' })
        }
    }

    const anchorElement = entry.anchorElement.isConnected ? entry.anchorElement : entry.fallbackAnchorElement

    return (
        <ActionPopup
            anchorElement={anchorElement}
            context={entry.context}
            draggable
            onClose={handleClose}
            onConversationViewed={handleConversationViewed}
            unseenResultActionIds={entry.unseenResultActionIds}
        />
    )
}

