    const { activeActionStatuses, adding, actions, onAdd, onSelect, selectedAction, unseenResultActionIds } = props

    const handleChange = (_event: MouseEvent<HTMLElement>, actionId: string | null) => {
        if (actionId) onSelect(actionId)
